resp_body:
/* Opsis Camera — Global Styles
 *
 * Unileap corporate theme: light professional UI aligned with www.unileap.ai
 * (navy #003087 primary, green #A4D233 accent, soft grey surfaces).
 */

* { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  /* Unileap brand palette */
  --brand: #003087;
  --brand-dark: #04245c;
  --brand-green: #A4D233;

  /* Surfaces */
  --bg-main: #f5f7fb;
  --bg-card: #ffffff;
  --bg-input: #f8fafd;
  --bg-light: #eef2f8;
  --border: #e7ebf2;
  --border-strong: #d9e0ec;

  /* Interactive (legacy names kept for page code) */
  --accent: #003087;
  --accent-hover: #04245c;
  --accent-soft: rgba(0, 48, 135, 0.08);

  /* Text (dim kept ≥4.5:1 on white for WCAG AA small text) */
  --text: #0e1626;
  --text-muted: #5b6678;
  --text-dim: #6d7789;

  /* Status */
  --ok: #2f9e44;
  --ok-bg: #e9f7ec;
  --err: #e03131;
  --err-bg: #fdecec;
  --warn: #e8940a;
  --warn-bg: #fff4e0;
  --danger: #e03131;
  --color-err: #e03131;

  --radius: 14px;
  --shadow: 0 1px 2px rgba(13, 22, 44, 0.05), 0 8px 24px rgba(13, 22, 44, 0.05);
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Noto Sans",
    "Noto Sans TC", Roboto, Arial, sans-serif;
  background: var(--bg-main);
  color: var(--text);
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
}

/* --- Header + Top Tabs --- */
header {
  background: var(--bg-card);
  padding: 0 1.5em;
  height: 60px;
  display: flex;
  align-items: center;
  gap: 2em;
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 100;
}

.brand {
  display: flex;
  align-items: center;
  gap: 0.9em;
  white-space: nowrap;
}
.brand__logo { height: 24px; display: block; }

header .status { font-size: 0.85em; font-weight: 600; color: var(--ok); margin-left: auto; }
header .status.is-off { color: var(--err); }

#top-tabs {
  display: flex;
  height: 100%;
  gap: 0;
}
#top-tabs a {
  display: flex;
  align-items: center;
  padding: 0 1.2em;
  color: var(--text-muted);
  text-decoration: none;
  font-size: 0.95em;
  font-weight: 600;
  border-bottom: 2px solid transparent;
  transition: color 0.2s, border-color 0.2s;
}
#top-tabs a:hover { color: var(--text); }
#top-tabs a.active {
  color: var(--brand);
  border-bottom-color: var(--brand);
}

/* --- Layout --- */
#layout {
  display: flex;
  min-height: calc(100vh - 60px);
  background: var(--bg-main);
}

/* Boxed shell on wide screens: header + sidebar + content form one centred
   frame (same idiom as unileap.ai's 1180px wrap), outer bg one step darker. */
@media (min-width: 1280px) {
  body { background: #e6eaf2; }
  header, #layout {
    max-width: 1240px;
    margin: 0 auto;
    border-left: 1px solid var(--border-strong);
    border-right: 1px solid var(--border-strong);
  }
}

/* --- Sidebar --- */
#sidebar {
  width: 200px;
  background: var(--bg-card);
  border-right: 1px solid var(--border);
  padding: 1em 0;
  flex-shrink: 0;
}
/* Section headers: Unileap "eyebrow" style — navy, uppercase, wide
   tracking — with a divider between groups for clear hierarchy. */
#sidebar .nav-section {
  margin-top: 0.9em;
  padding: 1em 1em 0.45em;
  font-size: 0.7em;
  font-weight: 800;
  color: var(--brand);
  text-transform: uppercase;
  letter-spacing: 0.14em;
  border-top: 1px solid var(--border);
}
#sidebar .nav-section:first-child {
  margin-top: 0;
  padding-top: 0.4em;
  border-top: none;
}
#sidebar a {
  display: flex;
  align-items: center;
  gap: 0.65em;
  padding: 0.45em 1em 0.45em 1.6em;
  color: var(--text-muted);
  text-decoration: none;
  font-size: 0.9em;
  border-left: 3px solid transparent;
}
#sidebar a svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  opacity: 0.75;
}
#sidebar a.active svg,
#sidebar a:hover svg { opacity: 1; }
#sidebar a:hover { color: var(--brand); background: rgba(0, 48, 135, 0.04); }
#sidebar a.active {
  color: var(--brand);
  font-weight: 600;
  background: var(--accent-soft);
  border-left-color: var(--brand);
}
#sidebar a.disabled {
  color: #b6bdc9;
  pointer-events: none;
}

/* --- Main content ---
 * Fills the space next to the sidebar; cards span it, individual
 * inputs are width-capped below so forms stay readable. */
#app {
  flex: 1;
  min-width: 0;
  padding: 1.5em 2em;
}

/* --- Card --- */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 1.5em;
  margin-bottom: 1.5em;
}
.card h2 {
  color: var(--brand);
  font-size: 1.1em;
  margin-bottom: 1em;
  border-bottom: 1px solid var(--border);
  padding-bottom: 0.5em;
}

/* --- Form fields --- */
.field {
  display: flex;
  align-items: center;
  margin-bottom: 0.8em;
}
.field label {
  width: 120px;
  font-size: 0.9em;
  color: var(--text-muted);
  flex-shrink: 0;
}
.field input, .field select {
  flex: 1;
  max-width: 440px;
  padding: 0.5em;
  background: var(--bg-card);
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  color: var(--text);
  font-size: 0.9em;
}
.field input:focus, .field select:focus {
  outline: none;
  border-color: var(--brand);
  box-shadow: 0 0 0 3px rgba(0, 48, 135, 0.12);
}
.field input[readonly] {
  background: var(--bg-input);
  color: var(--text-muted);
}

/* --- Form grid (settings pages) --- */
.form-grid {
  display: grid;
  grid-template-columns: 140px 1fr;
  gap: 0.6em 1em;
  align-items: center;
  margin-bottom: 1em;
}
.form-grid label { font-size: 0.9em; color: var(--text-muted); }
.form-grid input, .form-grid select, .form-grid textarea {
  max-width: 440px;
  padding: 0.5em;
  background: var(--bg-card);
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  color: var(--text);
  font-size: 0.9em;
}
/* Denser variant for settings forms: labels never wrap, controls don't
 * stretch across the card. */
.form-grid--compact { grid-template-columns: 170px minmax(200px, 340px); }
.form-grid input:focus, .form-grid select:focus, .form-grid textarea:focus {
  outline: none;
  border-color: var(--brand);
  box-shadow: 0 0 0 3px rgba(0, 48, 135, 0.12);
}

/* --- Toggle switch --- */
.toggle {
  display: flex;
  align-items: center;
  gap: 0.6em;
  cursor: pointer;
}
.toggle input[type="checkbox"] {
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
  box-sizing: border-box;
  margin: 0;
  width: 40px;
  height: 22px;
  min-width: 40px;
  background: var(--border-strong);
  border: none;
  border-radius: 11px;
  position: relative;
  cursor: pointer;
  transition: background 0.2s;
  flex-shrink: 0;
  vertical-align: middle;
}
.toggle input[type="checkbox"]::after {
  content: '';
  position: absolute;
  top: 50%;
  margin-top: -8px;        /* half the knob height: vertical centre */
  left: 3px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 1px 3px rgba(13, 22, 44, 0.25);
  transition: left 0.2s, background 0.2s;
}
.toggle input[type="checkbox"]:checked {
  background: var(--brand);
}
.toggle input[type="checkbox"]:checked::after {
  left: 21px;              /* 40 - 16 - 3 = right margin 3px */
  background: #fff;
}
.toggle-label {
  font-size: 0.85em;
  color: var(--text-muted);
}

.form-note {
  font-size: 0.82em;
  color: var(--text-dim);
  margin: -0.3em 0 1em;
  line-height: 1.45;
}
.form-note a {
  color: var(--brand);
  font-weight: 600;
}

/* --- Card description (subtitle under h2) --- */
.hint {
  font-size: 0.88em;
  color: var(--text-muted);
  line-height: 1.55;
  margin: -0.4em 0 1.1em;
}

/* --- Info callout (cross-feature tips, notices) --- */
.callout {
  display: flex;
  align-items: flex-start;
  gap: 0.6em;
  font-size: 0.85em;
  color: var(--brand-dark);
  background: var(--accent-soft);
  border: 1px solid rgba(0, 48, 135, 0.18);
  border-radius: 8px;
  padding: 0.7em 0.9em;
  margin-bottom: 1.1em;
  line-height: 1.5;
}
.callout svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  margin-top: 0.15em;
  stroke: var(--brand);
}
.callout a {
  color: var(--brand);
  font-weight: 600;
}

/* Warning variant: consequence/risk notices (vs neutral info) */
.callout--warn {
  color: #7a4b00;
  background: var(--warn-bg);
  border-color: rgba(232, 148, 10, 0.5);
}
.callout--warn svg { stroke: #b26a00; }

/* --- Form static (read-only) --- */
.status-ok { color: var(--ok); font-weight: 600; }
.status-err { color: var(--err); font-weight: 600; }

.form-static {
  font-size: 0.9em;
  color: var(--text);
  padding: 0.5em 0;
}

/* --- Form actions --- */
.form-actions {
  display: flex;
  gap: 0.8em;
  margin-top: 1.2em;
  padding-top: 1em;
  border-top: 1px solid var(--border);
}

/* --- Image (ISP) page: slider rows, advanced disclosure --- */
.slider-row {
  display: flex;
  align-items: center;
  gap: 0.8em;
}
.slider-row input[type="range"] {
  flex: 1;
  padding: 0;
  background: transparent;
  border: none;
}
.slider-row output {
  min-width: 2.5em;
  text-align: right;
  font-size: 0.9em;
  color: var(--text-muted);
}
.form-grid input[type="checkbox"] {
  width: 1.1em;
  height: 1.1em;
  padding: 0;
  justify-self: start;
  accent-color: var(--brand);
}
details.advanced {
  margin-top: 1em;
  border-top: 1px solid var(--border);
  padding-top: 0.6em;
}
details.advanced > summary {
  cursor: pointer;
  font-weight: 600;
  margin-bottom: 0.6em;
}
p.muted {
  color: var(--text-muted);
  font-size: 0.85em;
  margin-top: 0.8em;
}
span.muted {
  color: var(--text-muted);
  font-size: 0.85em;
}
/* Locked recordings (playback list): protected from circular overwrite */
tr.rec-locked td { background: color-mix(in srgb, var(--brand) 6%, transparent); }

/* Storage volume cards (Storage → Management) */
.vol-card {
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.7em 0.9em;
  margin-bottom: 0.7em;
}
.vol-card__head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 0.6em;
  margin-bottom: 0.5em;
}
.vol-card__meta { margin-top: 0.4em; }
.vol-health--bad { color: var(--err, #d33); font-size: 0.85em; }
.vol-health--ok { color: var(--ok, #2f9e44); font-size: 0.85em; }
.vol-card__tools { margin-left: auto; display: inline-flex; gap: 6px; }
.vol-card--warn {
  border-color: var(--warn, #e8940a);
  background: color-mix(in srgb, #e8940a 8%, transparent);
}

/* Event recording window widget (Storage → Management): the bar mirrors
 * the pre/post sliders so the numbers have a picture. */
.ev-rec {
  border-top: 1px solid var(--border);
  margin-top: 1em;
  padding-top: 0.8em;
}
.ev-rec__title { margin: 0 0 0.3em; font-size: 1em; }
.ev-bar {
  display: flex;
  align-items: stretch;
  height: 26px;
  border-radius: 6px;
  overflow: hidden;
  border: 1px solid var(--border);
  margin: 6px 0 10px;
}
.ev-bar__pre, .ev-bar__post {
  flex-grow: 1;
  flex-basis: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.72em;
  color: var(--text-muted);
  transition: flex-grow 0.1s;
  min-width: 20px;
}
.ev-bar__pre { background: color-mix(in srgb, var(--brand) 18%, transparent); }
.ev-bar__post { background: color-mix(in srgb, #2f9e44 18%, transparent); }
.ev-bar__mark {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  padding: 0 4px;
  background: var(--warn, #e8940a);
  color: #fff;
  font-size: 0.8em;
}
.ev-rec__sliders {
  display: flex;
  flex-wrap: wrap;
  gap: 1.2em;
  align-items: center;
}
.ev-rec__sliders label {
  display: flex;
  align-items: center;
  gap: 0.5em;
  font-size: 0.9em;
}
.ev-rec__sliders input[type="range"] { width: 140px; }
.ev-rec__val { min-width: 2.5em; text-align: right; color: var(--text-muted); }

/* Disk recycling watermark bar: zones sized by the three thresholds */
.wm-bar {
  display: flex;
  align-items: stretch;
  height: 26px;
  border-radius: 6px;
  overflow: hidden;
  border: 1px solid var(--border);
  margin: 6px 0 10px;
  transition: opacity 0.15s;
}
.wm-bar__seg {
  flex-grow: 1;
  flex-basis: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.72em;
  color: var(--text-muted);
  transition: flex-grow 0.1s;
  min-width: 4px;
}
.wm-bar__ok      { background: color-mix(in srgb, #2f9e44 16%, transparent); }
.wm-bar__band    { background: color-mix(in srgb, #e8c40a 20%, transparent); }
.wm-bar__recycle { background: color-mix(in srgb, var(--warn, #e8940a) 30%, transparent); }
.wm-bar__stop    { background: color-mix(in srgb, #d33 35%, transparent); }
.wm-bar__dead    { background: color-mix(in srgb, var(--text-muted, #888) 18%, transparent); }

/* Threshold ticks under the bar and a live usage marker on it: the bar,
 * the numbers and the sliders share one color per boundary. */
.wm-bar--linked { position: relative; margin-bottom: 24px; overflow: visible; }
.wm-bar--linked .wm-bar__seg:first-child { border-radius: 6px 0 0 6px; }
.wm-bar--linked .wm-bar__seg--last { border-radius: 0 6px 6px 0; }
.wm-bar__tick {
  position: absolute;
  top: calc(100% + 2px);
  transform: translateX(-50%);
  font-size: 0.72em;
  font-weight: 600;
}
.wm-bar__now {
  position: absolute;
  top: -3px;
  bottom: -3px;
  width: 2px;
  background: var(--text);
  opacity: 0.75;
}
.wm-bar__now span {
  position: absolute;
  left: 4px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 0.72em;
  font-weight: 600;
  color: var(--text);
  white-space: nowrap;
}
.wm-dot {
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  margin-right: 4px;
  vertical-align: baseline;
}
#cfg-low      { accent-color: #cfa50a; }
#cfg-high     { accent-color: var(--warn, #e8940a); }
#cfg-critical { accent-color: #d33; }
#cfg-pre      { accent-color: var(--brand, #003087); }
#cfg-post     { accent-color: #2f9e44; }
#cfg-retention-event { accent-color: var(--brand, #003087); }

/* Inline note inside a rule action's parameter row (record: pre/post hint) */
.ar-note {
  display: block;
  width: 100%;
  font-size: 0.8em;
  margin-bottom: 2px;
}

/* --- Range slider --- */
.range-group {
  display: flex;
  align-items: center;
  gap: 0.8em;
}
.range-group input[type="range"] {
  flex: 1;
  appearance: none;
  height: 6px;
  background: var(--border-strong);
  border-radius: 3px;
  outline: none;
}
.range-group input[type="range"]::-webkit-slider-thumb {
  appearance: none;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--brand);
  cursor: pointer;
}
.range-group span {
  min-width: 2em;
  text-align: right;
  font-size: 0.9em;
  color: var(--text);
  font-weight: bold;
}

/* --- Fieldset sub-sections (settings groups) --- */
.card fieldset {
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 1.1em 1.2em 0.9em;
  margin: 1.6em 0;
  min-width: 0;
}
.card fieldset > .field:last-child,
.card fieldset > .ev-row:last-child { margin-bottom: 0.2em; }
.card legend {
  font-size: 0.75em;
  font-weight: 800;
  color: var(--brand);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  padding: 0 0.6em;
}

/* --- Section header inside card --- */
.card h3 {
  font-size: 0.95em;
  color: var(--text);
  margin: 1.2em 0 0.6em;
  padding-bottom: 0.3em;
  border-bottom: 1px solid var(--border);
}
.card h3:first-of-type {
  margin-top: 0;
}

/* --- Coming soon badge --- */
.badge-coming-soon {
  font-size: 0.75em;
  font-weight: normal;
  color: var(--text-dim);
  background: var(--bg-light);
  padding: 0.15em 0.5em;
  border-radius: 4px;
  margin-left: 0.5em;
  vertical-align: middle;
}

/* --- Disabled toggle --- */
.toggle--disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.toggle--disabled input[type="checkbox"] {
  cursor: not-allowed;
}

/* --- Stream URLs (RTSP) --- */
.card__footer {
  margin-top: 1.5em;
  padding-top: 1em;
  border-top: 1px solid var(--border);
}
.stream-urls {
  font-size: 0.85em;
  color: var(--text-muted);
  line-height: 1.8;
}
.stream-urls code {
  background: var(--bg-light);
  padding: 0.2em 0.5em;
  border-radius: 4px;
  font-family: 'SF Mono', monospace;
  color: var(--brand);
  font-size: 0.9em;
}

/* --- Buttons --- */
.actions {
  display: flex;
  gap: 0.8em;
  margin-top: 1.2em;
}
button {
  padding: 0.6em 1.5em;
  border: 1px solid transparent;
  border-radius: 999px;
  cursor: pointer;
  font-size: 0.9em;
  font-weight: 600;
  transition: background 0.18s, border-color 0.18s, color 0.18s;
}
.btn-primary {
  background: var(--brand);
  color: #fff;
  font-weight: 700;
}
.btn-primary:hover { background: var(--brand-dark); }
.btn-secondary {
  background: var(--bg-card);
  border-color: var(--border-strong);
  color: var(--text);
}
.btn-secondary:hover { border-color: var(--brand); color: var(--brand); }
.btn-danger {
  background: var(--err);
  color: #fff;
  font-weight: 700;
}
.btn-danger:hover { background: #c22525; }

/* Disabled buttons read as disabled regardless of variant — a solid
 * red Delete that does nothing (last-admin guard) must not look live. */
button:disabled,
.btn-primary:disabled, .btn-secondary:disabled, .btn-danger:disabled,
.btn-small:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  filter: grayscale(0.35);
}
button:disabled:hover,
.btn-danger:disabled:hover { background: var(--err); }
.btn-primary:disabled:hover { background: var(--brand); }

/* --- Info table --- */
.info-table {
  width: 100%;
  border-collapse: collapse;
}
.info-table td {
  padding: 0.4em 0;
  font-size: 0.9em;
}
.info-table td:first-child {
  color: var(--text-muted);
  width: 140px;
}

/* --- Toast notifications --- */
#toast-container {
  position: fixed;
  top: 1em;
  right: 1em;
  z-index: 1000;
  display: flex;
  flex-direction: column;
  gap: 0.5em;
}
.toast {
  padding: 0.6em 1.2em;
  border-radius: 8px;
  font-size: 0.85em;
  font-weight: 600;
  border: 1px solid transparent;
  box-shadow: var(--shadow);
  animation: toast-in 0.3s ease;
}
.toast.ok { background: var(--ok-bg); color: #23763a; border-color: rgba(47, 158, 68, 0.35); }
.toast.err { background: var(--err-bg); color: #b02525; border-color: rgba(224, 49, 49, 0.35); }
.toast.warn { background: var(--warn-bg); color: #9a6700; border-color: rgba(232, 148, 10, 0.4); }

@keyframes toast-in {
  from { opacity: 0; transform: translateX(1em); }
  to { opacity: 1; transform: translateX(0); }
}

/* --- Layout mode: live (no sidebar, centred player column) --- */
#layout.layout--live #sidebar { display: none; }
#layout.layout--live #app {
  max-width: 1080px;
  margin: 0 auto;
}

/* Player card (wren-pvm style): topbar + video stage + control strip
   presented as one contained card. */
.lv-player {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  overflow: hidden;
}
.lv-player:fullscreen {
  display: flex;
  flex-direction: column;
  border: none;
  border-radius: 0;
  background: #000;
}
.lv-player:fullscreen .lv-body { flex: 1; min-height: 0; }
.lv-player:fullscreen .lv-stage { aspect-ratio: auto; }

/* ── Top bar: camera name + stream selector + connection badge ── */
.lv-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1em;
  padding: 0.55em 1em;
  background: var(--bg-card);
  border-bottom: 1px solid var(--border);
  flex-shrink: 0;
}
.lv-topbar__left,
.lv-topbar__right { display: flex; align-items: center; gap: 0.75em; position: relative; }

/* Detection overlay filter popover */
.lv-detect-pop {
	position: absolute;
	top: calc(100% + 0.5em);
	right: 2.6em;
	z-index: 30;
	min-width: 15em;
	background: #fff;
	border: 1px solid var(--border, #d8dee6);
	border-radius: 8px;
	box-shadow: 0 6px 24px rgba(16, 34, 60, 0.14);
	padding: 0.6em 0.85em;
	text-align: left;
}
.lv-dtp__row {
	display: flex;
	align-items: center;
	gap: 0.5em;
	padding: 0.28em 0;
	font-size: 0.86em;
	cursor: pointer;
	white-space: nowrap;
}
.lv-dtp__master { font-weight: 600; }
.lv-dtp__sep { border-top: 1px solid var(--border, #e3e8ef); margin: 0.35em 0; }
.lv-dtp__swatch {
	display: inline-block;
	width: 0.85em;
	height: 0.85em;
	border-radius: 2px;
	border: 2px solid;
	flex: none;
}
.lv-dtp__swatch--motion { border-color: #d9b512; border-style: dashed; }
.lv-dtp__swatch--person { border-color: #7fa823; }
.lv-dtp__swatch--vehicle { border-color: #e08a2e; }
.lv-dtp__swatch--animal { border-color: #c084fc; }
.lv-dtp__swatch--object { border-color: #4aa3ff; }
.lv-dtp__conf { justify-content: space-between; margin-top: 0.2em; }
.lv-dtp__conf select { font-size: 1em; padding: 0.1em 0.3em; }
.lv-dtp__hint {
	margin: 0.5em 0 0;
	font-size: 0.75em;
	color: var(--text-dim, #7a8699);
	white-space: normal;
}

/* Small dot on the detect button when a display filter is active */
.btn-icon.is-filtered::after {
	content: '';
	position: absolute;
	top: 0.28em;
	right: 0.28em;
	width: 0.45em;
	height: 0.45em;
	border-radius: 50%;
	background: var(--accent, #a4d233);
}
.btn-icon { position: relative; }

.lv-streamicon { display: inline-flex; align-items: center; color: var(--brand); }
.lv-streamicon svg { width: 18px; height: 18px; }

.stream-select {
  padding: 0.35em 0.7em;
  background: var(--bg-card);
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  color: var(--text);
  font-size: 0.85em;
}
.stream-select:focus { outline: none; border-color: var(--brand); }

/* Connection badge */
.lv-badge {
  display: inline-flex; align-items: center; gap: 0.4em;
  font-size: 0.72em; font-weight: 600; letter-spacing: 0.05em; text-transform: uppercase;
  color: var(--text-dim); background: var(--bg-light);
  padding: 0.32em 0.65em; border-radius: 999px; border: 1px solid var(--border);
}
.lv-badge .lv-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--text-dim); }
.live-view.is-live .lv-badge { color: var(--ok); border-color: rgba(47,158,68,0.4); background: var(--ok-bg); }
.live-view.is-live .lv-badge .lv-dot {
  background: var(--ok); animation: lv-pulse-ok 1.6s infinite;
}

.btn-icon {
  background: var(--bg-card); border: 1px solid var(--border-strong); border-radius: 8px;
  color: var(--text); padding: 0.35em 0.55em; font-size: 1.05em; cursor: pointer;
  line-height: 1; display: inline-flex; align-items: center;
}
.btn-icon svg { width: 16px; height: 16px; }
.btn-icon:hover { background: var(--accent-soft); border-color: var(--brand); color: var(--brand); }

/* ── Player body: video stage + collapsible PTZ drawer ── */
.lv-body { display: flex; align-items: stretch; }

.lv-ptzpanel {
  width: 0;
  overflow: hidden;
  flex-shrink: 0;
  background: var(--bg-card);
  border-left: 0 solid var(--border);
  transition: width 0.25s ease, border-left-width 0.25s ease;
}
.live-view.is-ptz-open .lv-ptzpanel {
  width: 216px;
  border-left-width: 1px;
}
.lv-ptzpanel__inner {
  width: 216px;               /* fixed: content keeps shape while sliding */
  padding: 1.1em 1em;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.1em;
}
.lv-ptzpanel__inner .lv-card__title { align-self: flex-start; margin-bottom: 0; }

.btn-icon.active {
  background: var(--accent-soft);
  border-color: var(--brand);
  color: var(--brand);
}

/* ── Video stage: fixed 16:9 area inside the player card ── */
.lv-stage {
  flex: 1;
  position: relative;
  aspect-ratio: 16 / 9;
  background: #000;
  min-width: 0;
  overflow: hidden;
}
.lv-stage video,
.lv-stage img {
  position: absolute; inset: 0;
  width: 100%; height: 100%; object-fit: contain;
}

/* Idle state: big circular play button in the middle (wren-pvm style). */
.lv-empty {
  position: absolute; inset: 0; z-index: 1;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1em;
  text-align: center; padding: 1em;
  background: radial-gradient(ellipse at center, #10182b 0%, #000 75%);
  cursor: pointer;
}
.lv-bigplay {
  width: 84px; height: 84px; border-radius: 50%;
  border: 4px solid rgba(255, 255, 255, 0.5);
  display: flex; align-items: center; justify-content: center;
  transition: border-color 0.25s, transform 0.25s;
}
.lv-bigplay svg {
  width: 34px; height: 34px; margin-left: 4px;
  fill: rgba(255, 255, 255, 0.65);
  transition: fill 0.25s;
}
.lv-empty:hover .lv-bigplay { border-color: rgba(255, 255, 255, 0.9); transform: scale(1.05); }
.lv-empty:hover .lv-bigplay svg { fill: rgba(255, 255, 255, 0.95); }
.lv-empty__hint { font-size: 0.85em; color: #8b95a7; }
.live-view.is-live .lv-empty { display: none; }

/* Video overlays */
.lv-overlay { position: absolute; z-index: 2; pointer-events: none; }
.lv-detect-canvas {
	position: absolute;
	inset: 0;
	width: 100%;
	height: 100%;
	z-index: 2;
	pointer-events: none;
}
/* Top-right, not top-left: the camera's own OSD (name and timestamp) is
 * burned into the top-left of the encoded frame, so a badge there covers
 * it. See osd_control.c OSD_POS_X/OSD_POS_Y. */
.lv-overlay--tr { top: 0.7em; right: 0.7em; }
.lv-overlay--bl { left: 0.7em; bottom: 0.7em; }

.lv-live {
  display: none; align-items: center; gap: 0.4em;
  font-size: 0.72em; font-weight: 700; letter-spacing: 0.08em; color: #fff;
  background: rgba(224,49,49,0.92); padding: 0.28em 0.6em; border-radius: 4px;
}
.lv-rec[hidden] { display: none; }
.lv-rec {
	display: inline-flex;
	align-items: center;
	gap: 0.35em;
	margin-left: 0.6em;
	padding: 0.15em 0.55em;
	border-radius: 4px;
	background: rgba(0, 0, 0, 0.55);
	color: #ff4d4d;
	font-size: 0.72em;
	font-weight: 700;
	letter-spacing: 0.08em;
}
.lv-rec__dot {
	width: 0.6em;
	height: 0.6em;
	border-radius: 50%;
	background: #ff4d4d;
	animation: lv-rec-blink 1.2s infinite;
}
@keyframes lv-rec-blink {
	50% { opacity: 0.25; }
}

.lv-live__dot { width: 7px; height: 7px; border-radius: 50%; background: #fff; animation: lv-pulse 1.4s infinite; }
.live-view.is-live .lv-live { display: inline-flex; }

.lv-osd {
  display: none; font-size: 0.75em; color: #fff; background: rgba(0,0,0,0.55);
  padding: 0.28em 0.6em; border-radius: 4px; font-variant-numeric: tabular-nums;
}
.live-view.is-live .lv-osd { display: inline-block; }

@keyframes lv-pulse {
  0% { box-shadow: 0 0 0 0 rgba(224,49,49,0.6); }
  70% { box-shadow: 0 0 0 6px rgba(224,49,49,0); }
  100% { box-shadow: 0 0 0 0 rgba(224,49,49,0); }
}
@keyframes lv-pulse-ok {
  0% { box-shadow: 0 0 0 0 rgba(47,158,68,0.6); }
  70% { box-shadow: 0 0 0 5px rgba(47,158,68,0); }
  100% { box-shadow: 0 0 0 0 rgba(47,158,68,0); }
}

/* One-line stream summary in the topbar */
.lv-inforow {
  font-size: 0.8em;
  color: var(--text-dim);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.lv-card__title {
  font-size: 0.76em; font-weight: 700; text-transform: uppercase; letter-spacing: 0.07em;
  color: var(--brand); margin-bottom: 0.9em;
}

/* PTZ pad + zoom/focus groups (inside the drawer) */
.ptz-pad {
  display: grid;
  grid-template-columns: repeat(3, 48px);
  gap: 6px;
}
.ptz-pad button {
  aspect-ratio: 1; padding: 0; font-size: 1em;
  background: var(--bg-input); border: 1px solid var(--border-strong); border-radius: 10px;
  color: var(--text); cursor: pointer; display: flex; align-items: center; justify-content: center;
}
.ptz-pad button:hover { background: var(--accent-soft); border-color: var(--brand); color: var(--brand); }
.ptz-pad button[data-dir="home"] { background: var(--accent-soft); color: var(--brand); border-color: rgba(0, 48, 135, 0.25); }

.lv-ptz__group {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.6em;
}
.lv-ptz__label {
  font-size: 0.75em;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-dim);
}
.lv-ptz__btns { display: flex; gap: 6px; }
.lv-ptz__btns button {
  width: 42px; height: 36px; padding: 0; font-size: 0.95em;
  background: var(--bg-input); border: 1px solid var(--border-strong); border-radius: 10px;
  color: var(--text); cursor: pointer;
}
.lv-ptz__btns button:hover { background: var(--accent-soft); border-color: var(--brand); color: var(--brand); }

/* ── Control strip attached under the video (icon buttons) ── */
.lv-controls {
  display: flex; align-items: center; justify-content: space-between; gap: 1em;
  padding: 0.35em 0.7em;
  background: var(--bg-card); border-top: 1px solid var(--border);
}
.lv-controls__left { display: flex; align-items: center; gap: 0.25em; }
.lv-controls__right {
  display: flex; align-items: center; gap: 0.6em;
  font-size: 0.82em; color: var(--text-dim);
  font-variant-numeric: tabular-nums; white-space: nowrap;
}
.lvc-btn {
  display: inline-flex; align-items: center; justify-content: center;
  width: 38px; height: 34px; padding: 0;
  background: transparent; border: none; border-radius: 8px;
  color: var(--text-muted); cursor: pointer;
}
.lvc-btn svg { width: 18px; height: 18px; }
.lvc-btn span { display: none; }   /* icon-only; labels stay for a11y/JS */
.lvc-btn:hover:not([disabled]) { background: var(--accent-soft); color: var(--brand); }
.lvc-btn[disabled] { opacity: 0.35; cursor: default; }
.lv-player:fullscreen .lv-controls { border-top-color: #1c2333; background: #0a0f1c; }
.lv-player:fullscreen .lvc-btn { color: #aeb7c6; }

/* Push-to-talk: highlight while transmitting (hold to talk). */
#btn-talk { touch-action: none; user-select: none; }
#btn-talk.is-talking {
  background: var(--danger, #e03131); border-color: var(--danger, #e03131); color: #fff;
  animation: lv-pulse 1.2s infinite;
}
#btn-talk.is-talking svg { stroke: #fff; }

/* Narrow screens: drop the inline stream summary (badge stays) */
@media (max-width: 760px) {
  .lv-inforow { display: none; }
}

/* Touch devices: grow interactive targets to >=44px (WCAG 2.5.8) */
@media (pointer: coarse) {
  .lvc-btn { width: 48px; height: 44px; }
  .lvc-btn svg { width: 20px; height: 20px; }
  .btn-icon { padding: 0.6em 0.8em; }
  .ptz-pad { grid-template-columns: repeat(3, 52px); }
  .lv-ptz__btns button { width: 48px; height: 44px; }
}

/* --- Dashboard --- */

/* Gauge row */
.gauge-row {
  display: flex;
  gap: 2em;
  justify-content: center;
  flex-wrap: wrap;
}

.gauge {
  text-align: center;
  min-width: 100px;
}

.gauge__circle {
  width: 90px;
  height: 90px;
  border-radius: 50%;
  background: conic-gradient(
    var(--ok) calc(var(--pct) * 1%),
    var(--bg-light) 0
  );
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 0.4em;
  position: relative;
}
.gauge--warn .gauge__circle {
  background: conic-gradient(
    var(--warn) calc(var(--pct) * 1%),
    var(--bg-light) 0
  );
}
.gauge--err .gauge__circle {
  background: conic-gradient(
    var(--err) calc(var(--pct) * 1%),
    var(--bg-light) 0
  );
}

.gauge__circle::after {
  content: '';
  position: absolute;
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: var(--bg-card);
}

.gauge__value {
  position: relative;
  z-index: 1;
  font-size: 1.1em;
  font-weight: bold;
  color: var(--text);
}

.gauge__label {
  font-size: 0.85em;
  color: var(--text-muted);
}

.gauge__detail {
  font-size: 0.75em;
  color: var(--text-dim);
  margin-top: 0.2em;
}

.dashboard__uptime {
  text-align: center;
  margin-top: 1em;
  font-size: 0.85em;
  color: var(--text-dim);
}

/* Topology */
.topo {
  overflow-x: auto;
  padding: 0.5em 0;
}

.topo__svg {
  width: 100%;
  min-width: 500px;
  height: auto;
}

.topo__node:hover rect {
  stroke-width: 3;
  filter: brightness(1.05);
}

.topo__legend {
  display: flex;
  gap: 1.2em;
  justify-content: center;
  margin-top: 0.8em;
  font-size: 0.8em;
  color: var(--text-dim);
}

.topo__legend-item {
  display: flex;
  align-items: center;
  gap: 0.3em;
}

/* Daemon cards grid */
.daemon-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 1em;
}

.daemon-card {
  background: var(--bg-input);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.8em 1em;
  border-left: 3px solid var(--text-dim);
}
.daemon-card--running { border-left-color: var(--ok); }
.daemon-card--unresponsive { border-left-color: var(--warn); }
.daemon-card--stopped { border-left-color: var(--err); }
.daemon-card--static { border-left-color: var(--text-dim); }
.daemon-card--not_deployed { border-left-color: var(--text-dim); }

.daemon-card__name {
  font-weight: bold;
  font-size: 0.95em;
  margin-bottom: 0.2em;
}

.daemon-card__meta {
  font-size: 0.8em;
  color: var(--text-muted);
  margin-bottom: 0.5em;
}

.daemon-card__cat {
  color: var(--text-dim);
}

.daemon-card__stat {
  font-size: 0.8em;
  color: var(--text-muted);
  padding: 0.1em 0;
}

/* --- Daemon restart detection --- */
.daemon-card--restarted {
  animation: card-blink 0.6s ease 3;
}
@keyframes card-blink {
  0%, 100% { background: var(--bg-input); }
  50% { background: rgba(232, 148, 10, 0.2); }
}
.daemon-card__restart-badge {
  font-size: 0.7em;
  font-weight: normal;
  color: #9a6700;
  background: var(--warn-bg);
  padding: 0.1em 0.4em;
  border-radius: 3px;
  margin-left: 0.4em;
}

/* --- Responsive: tablet (<=768px) --- */
@media (max-width: 768px) {
  header { padding: 0 0.8em; gap: 0.5em; }
  .brand__logo { height: 20px; }

  #sidebar { width: 160px; }
  #sidebar a { padding: 0.4em 0.6em 0.4em 1em; font-size: 0.85em; }

  #app { padding: 1em; }

  .gauge-row { gap: 1em; }
  .gauge__circle { width: 72px; height: 72px; }
  .gauge__circle::after { width: 50px; height: 50px; }
  .gauge__value { font-size: 0.95em; }

  .daemon-grid {
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 0.6em;
  }

  .topo__svg { min-width: 400px; }


  .form-grid { grid-template-columns: 120px 1fr; gap: 0.5em 0.8em; }
}

/* --- Responsive: mobile (<=480px) --- */
@media (max-width: 480px) {
  /* Keep the Live View / Settings tabs — hiding them stranded phones on
   * whichever page they landed on. Compact them instead. */
  header { padding: 0 0.6em; gap: 0.8em; }
  #top-tabs { gap: 0.9em; flex: none; }
  #top-tabs a { padding: 0 0.15em; font-size: 0.9em; }
  header .user-menu__name { display: none; }  /* keep Online + logout only */

  #layout { flex-direction: column; }
  #sidebar {
    width: 100%;
    border-right: none;
    border-bottom: 1px solid var(--border);
    padding: 0.5em 0;
    overflow-x: auto;
    white-space: nowrap;
    display: flex;
    flex-wrap: nowrap;
  }
  #sidebar .nav-section { display: none; }
  #sidebar a {
    display: inline-flex;
    padding: 0.4em 0.8em;
    white-space: nowrap;
    border-left: none;
  }

  #app { padding: 0.8em; }
  .card { padding: 1em; margin-bottom: 1em; }
  .card h2 { font-size: 1em; }

  .gauge-row { gap: 0.8em; }
  .gauge__circle { width: 64px; height: 64px; }
  .gauge__circle::after { width: 44px; height: 44px; }
  .gauge__value { font-size: 0.85em; }

  .daemon-grid {
    grid-template-columns: 1fr;
    gap: 0.5em;
  }


  .topo__svg { min-width: 320px; }
  .topo__legend { flex-wrap: wrap; gap: 0.5em; font-size: 0.75em; }

  .form-grid { grid-template-columns: 1fr; gap: 0.4em; }
  .form-grid label { margin-top: 0.3em; }
}

/* --- Data table (user management etc.) --- */
.data-table {
  width: 100%;
  border-collapse: collapse;
}
.data-table thead th {
  text-align: left;
  font-size: 0.8em;
  color: var(--text-dim);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding: 0.5em 0.8em;
  border-bottom: 1px solid var(--border-strong);
}
.data-table tbody td {
  padding: 0.6em 0.8em;
  font-size: 0.9em;
  border-bottom: 1px solid var(--border);
}
.data-table tbody tr:hover {
  background: rgba(0, 48, 135, 0.03);
}
.data-table .empty-row td {
  color: var(--text-dim);
  text-align: center;
  padding: 1.5em;
}

/* --- Role badges --- */
.badge {
  display: inline-block;
  font-size: 0.78em;
  font-weight: 600;
  padding: 0.15em 0.55em;
  border-radius: 4px;
  text-transform: capitalize;
}
.badge-admin {
  color: #b02525;
  background: var(--err-bg);
}
.badge-operator {
  color: #9a6700;
  background: var(--warn-bg);
}
.badge-viewer {
  color: var(--brand);
  background: var(--accent-soft);
}

/* --- Small button --- */
.btn-small {
  padding: 0.3em 0.8em;
  font-size: 0.8em;
}

/* --- Form group / row (server settings) --- */
.form-group {
  margin-bottom: 0.8em;
}
.form-group label {
  display: block;
  font-size: 0.85em;
  color: var(--text-muted);
  margin-bottom: 0.3em;
}
.form-group input,
.form-group select {
  width: 100%;
  padding: 0.5em;
  background: var(--bg-card);
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  color: var(--text);
  font-size: 0.9em;
}
.form-group input:focus,
.form-group select:focus {
  outline: none;
  border-color: var(--brand);
  box-shadow: 0 0 0 3px rgba(0, 48, 135, 0.12);
}

.form-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1em;
  align-items: end;
}

@media (max-width: 480px) {
  .form-row { grid-template-columns: 1fr; }
}

/* --- System Log --- */

/* Output level bar */
.log-output-level {
  display: flex;
  align-items: center;
  gap: 0.8em;
  margin-bottom: 1.2em;
  padding: 0.8em 1em;
  background: var(--bg-input);
  border-radius: 8px;
  border: 1px solid var(--border);
}
.log-output-level__label {
  font-size: 0.85em;
  color: var(--text-muted);
  font-weight: 600;
  white-space: nowrap;
}

/* Filter bar */
.log-filters {
  display: flex;
  align-items: center;
  gap: 0.6em;
  margin-bottom: 1em;
  flex-wrap: wrap;
}

/* Shared select/input styling for log page */
.log-select {
  padding: 0.4em 0.6em;
  background: var(--bg-card);
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  color: var(--text);
  font-size: 0.85em;
}
.log-select:focus {
  outline: none;
  border-color: var(--brand);
}

.log-search {
  flex: 1;
  min-width: 140px;
  padding: 0.4em 0.6em;
  background: var(--bg-card);
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  color: var(--text);
  font-size: 0.85em;
}
.log-search:focus {
  outline: none;
  border-color: var(--brand);
}
.log-search::placeholder {
  color: var(--text-dim);
}

.log-auto-refresh {
  margin-left: auto;
  white-space: nowrap;
}

/* Table wrapper */
.log-table-wrap {
  overflow-x: auto;
  border: 1px solid var(--border);
  border-radius: 8px;
}

/* Log table — extends data-table */
.log-table {
  font-size: 0.85em;
}
.log-table thead th {
  position: sticky;
  top: 0;
  background: var(--bg-input);
  z-index: 1;
}
.log-table tbody tr:hover {
  background: rgba(0, 48, 135, 0.04);
}

/* Column widths */
.log-col-time {
  width: 130px;
  white-space: nowrap;
  font-family: 'SF Mono', 'Consolas', monospace;
  font-size: 0.92em;
}
.log-col-daemon {
  width: 90px;
  white-space: nowrap;
}
.log-col-level {
  width: 36px;
  text-align: center;
}
.log-col-msg {
  word-break: break-word;
  font-family: 'SF Mono', 'Consolas', monospace;
  font-size: 0.92em;
}

/* Level badges */
.log-badge {
  display: inline-block;
  width: 22px;
  height: 22px;
  line-height: 22px;
  text-align: center;
  border-radius: 4px;
  font-size: 0.8em;
  font-weight: 700;
}
.log-badge--error {
  color: #fff;
  background: var(--err);
}
.log-badge--warning {
  color: #8a5400;
  background: var(--warn-bg);
  border: 1px solid rgba(232, 148, 10, 0.5);
}
.log-badge--info {
  color: var(--text-muted);
  background: var(--bg-light);
}
.log-badge--debug {
  color: var(--text-dim);
  background: var(--bg-input);
}

/* Footer: pagination + actions */
.log-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 1em;
  flex-wrap: wrap;
  gap: 0.8em;
}

.log-pagination {
  display: flex;
  align-items: center;
  gap: 0.6em;
}

.log-page-info {
  font-size: 0.85em;
  color: var(--text-muted);
  min-width: 12em;
  text-align: center;
}

.log-actions {
  display: flex;
  gap: 0.6em;
}

/* Responsive */
@media (max-width: 768px) {
  .log-filters { gap: 0.4em; }
  .log-auto-refresh { margin-left: 0; }
  .log-col-daemon { display: none; }
  .log-col-time { width: 100px; font-size: 0.85em; }
}

@media (max-width: 480px) {
  .log-output-level { flex-wrap: wrap; }
  .log-footer { flex-direction: column; align-items: stretch; }
  .log-pagination { justify-content: center; }
  .log-actions { justify-content: center; }
}

/* --- Storage: Progress Bar --- */
.progress-bar { height: 12px; background: var(--bg-light); border-radius: 6px; overflow: hidden; }
.progress-fill { height: 100%; background: var(--brand); transition: width 0.3s, background 0.3s; }
.progress-fill--warn { background: var(--warn); }
.progress-fill--crit { background: var(--err); }

/* --- Storage: Schedule Grid --- */
.sched-toolbar { display: flex; gap: 16px; margin-bottom: 8px; }
.sched-toolbar label { display: flex; align-items: center; gap: 4px; cursor: pointer; }
.sched-legend { padding: 2px 8px; border-radius: 4px; font-size: 0.85em; }
.sched-off-label { background: var(--bg-light); }
.sched-cont-label { background: var(--brand); color: #fff; }
.sched-event-label { background: var(--ok); color: #fff; }

/* The chips ARE the selector: the picked brush is lit and ticked, the
 * rest dim — the native radio dot was far too easy to miss (looked like
 * "selecting Continuous does nothing"). */
.sched-toolbar input[type="radio"] {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}
.sched-toolbar .sched-legend { opacity: 0.45; transition: opacity 0.12s, box-shadow 0.12s; }
.sched-toolbar input:checked + .sched-legend {
  opacity: 1;
  box-shadow: 0 0 0 2px var(--bg-card), 0 0 0 4px var(--text);
}
.sched-toolbar input:checked + .sched-legend::before { content: "\2713 "; }
.sched-toolbar input:focus-visible + .sched-legend {
  outline: 2px solid var(--brand);
  outline-offset: 3px;
}

/* Snapshot gallery hour bar: one cell per hour, heat = photo count */
.sn-hourbar {
  display: flex;
  height: 26px;
  border: 1px solid var(--border);
  border-radius: 6px;
  overflow: hidden;
}
.sn-hourcell {
  flex: 1;
  padding: 0;
  border: none;
  border-right: 1px solid var(--border);
  background: var(--bg-light);
  cursor: pointer;
  position: relative;
}
.sn-hourcell:last-child { border-right: none; }
.sn-hourcell i { position: absolute; inset: 0; display: block; background: var(--brand); }
.sn-hourcell--empty { cursor: default; }
.sn-hourcell--empty i { display: none; }
.sn-hourcell:not([disabled]):hover { outline: 2px solid var(--warn, #e8940a); outline-offset: -2px; z-index: 1; }
.sn-hourcell.active { outline: 2px solid var(--text); outline-offset: -2px; z-index: 1; }
.sn-hourlabels {
  display: flex;
  justify-content: space-between;
  font-size: 0.72em;
  color: var(--text-muted);
  margin-top: 2px;
}

/* Snapshot gallery lightbox */
.sn-lightbox {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.85);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  cursor: zoom-out;
}
.sn-lightbox figure { margin: 0; max-width: 92vw; max-height: 92vh; text-align: center; }
.sn-lightbox img { max-width: 92vw; max-height: 84vh; border-radius: 6px; }
.sn-lightbox figcaption {
  color: #fff;
  margin-top: 8px;
  display: flex;
  gap: 12px;
  align-items: center;
  justify-content: center;
}

/* Playback: the player, timeline and list act as one unit */
.pb-player {
  display: block;
  width: 100%;
  height: 360px;          /* fixed stage: no layout jump on load/unload */
  background: #000;
  border-radius: 8px;
  object-fit: contain;    /* clips letterbox inside instead of resizing */
}
#rec-tbody tr[data-rec] { cursor: pointer; }
#rec-tbody tr[data-rec]:hover { background: color-mix(in srgb, var(--brand) 5%, transparent); }
#rec-tbody tr.rec-playing { background: color-mix(in srgb, var(--brand) 12%, transparent); }
.tl-seg.tl-playing { outline: 2px solid var(--text); outline-offset: 1px; z-index: 1; }
.tl-playhead {
  position: absolute;
  top: -3px;
  bottom: -3px;
  width: 2px;
  background: var(--err, #d33);
  box-shadow: 0 0 3px color-mix(in srgb, var(--err, #d33) 80%, transparent);
  z-index: 2;
  pointer-events: none;
}

.sched-grid { overflow-x: auto; }
/* Horizontal week grid: days as rows, half-hour slots as columns.
 * The whole week is visible at once — no vertical scrolling. */
.sched-h { border-collapse: collapse; font-size: 0.75em; user-select: none; }
.sched-h th { font-weight: 600; color: var(--text-muted); padding: 0 0 4px; text-align: left; }
.sched-h-day {
  font-weight: 600; color: var(--text-muted); padding-right: 8px;
  white-space: nowrap; text-align: right;
}
.sched-hc {
  width: 14px; min-width: 14px; height: 20px; cursor: pointer;
  border: 1px solid var(--border); background: var(--bg-light);
}
.sched-hc:hover { outline: 2px solid var(--brand); outline-offset: -1px; }
.sched-cont { background: var(--brand); }
.sched-event { background: var(--ok); }

/* --- Storage: Playback Layout --- */
.playback-layout { display: grid; grid-template-columns: 220px 1fr; gap: 16px; }
.playback-sidebar { position: sticky; top: 16px; align-self: start; }

/* Calendar */
.cal-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; }
.cal-header button { background: none; border: 1px solid var(--border-strong); color: var(--text); padding: 2px 8px; cursor: pointer; border-radius: 6px; }
.cal-grid { font-size: 0.85em; }
.cal-row { display: grid; grid-template-columns: repeat(7, 1fr); gap: 2px; }
.cal-cell { text-align: center; padding: 4px 0; border-radius: 6px; }
.cal-hdr { font-weight: bold; color: var(--text-dim); }
.cal-day { cursor: pointer; }
.cal-day:hover { background: var(--bg-light); }
.cal-has-rec { color: var(--brand); font-weight: bold; }
.cal-has-rec::after { content: ''; display: block; width: 4px; height: 4px; border-radius: 50%; background: var(--brand); margin: 1px auto 0; }
.cal-selected { background: var(--brand); color: #fff; font-weight: bold; }

/* Timeline */
.timeline { margin: 8px 0; }
/* M3.2: zoomable timeline — the inner track grows wider than the viewport
 * (100% / 400% / 2400%) and the wrap scrolls horizontally = panning. */
.tl-zoom { display: flex; gap: 6px; margin-bottom: 6px; }
.timeline-wrap { overflow-x: auto; padding-bottom: 4px; }
.tl-inner { min-width: 100%; }
.timeline-bar { position: relative; height: 24px; background: var(--bg-light); border-radius: 6px; cursor: crosshair; }
/* Export range selection: orange stripes so it reads against both the
 * navy continuous and green event segments (a flat brand-blue wash was
 * invisible on top of continuous footage). */
.tl-select {
  position: absolute;
  top: -3px;
  bottom: -3px;
  height: auto;
  background: repeating-linear-gradient(45deg,
    color-mix(in srgb, var(--warn, #e8940a) 55%, transparent) 0 6px,
    color-mix(in srgb, var(--warn, #e8940a) 20%, transparent) 6px 12px);
  border: 2px solid var(--warn, #e8940a);
  border-radius: 3px;
  z-index: 2;
  pointer-events: none;
}
#tl-export { display: flex; align-items: center; gap: 8px; margin-top: 6px; }
.tl-seg { position: absolute; top: 0; height: 100%; border-radius: 2px; opacity: 0.85; }
.tl-cont { background: var(--brand); }
/* AI detection markers overlaid on the timeline (B3 Phase 2) */
.tl-det { position: absolute; top: -3px; width: 4px; height: 30px; border-radius: 2px;
  transform: translateX(-2px); box-shadow: 0 0 0 1px var(--bg-card); }
.tl-det:hover { width: 6px; transform: translateX(-3px); z-index: 2; }
.tl-event { background: var(--ok); }
.timeline-labels { display: flex; justify-content: space-between; font-size: 0.75em; color: var(--text-dim); margin-top: 2px; }

/* Recording list badges */
.badge { padding: 2px 6px; border-radius: 4px; font-size: 0.8em; }
.badge-cont { background: var(--brand); color: #fff; }
.badge-event { background: var(--ok); color: #fff; }
.badge-manual { background: var(--warn-bg); color: #8a5400; border: 1px solid rgba(232, 148, 10, 0.5); }
.btn-sm { padding: 2px 8px; font-size: 0.8em; background: var(--bg-card); border: 1px solid var(--border-strong); color: var(--text); cursor: pointer; border-radius: 6px; text-decoration: none; }
.btn-sm:hover { background: var(--brand); border-color: var(--brand); color: #fff; }

@media (max-width: 768px) {
  .playback-layout { grid-template-columns: 1fr; }
  .playback-sidebar { position: static; }
}

/* --- Misc --- */
.info { font-size: 0.85em; color: var(--text-dim); }
.hidden { display: none; }

/* --- Event / Alarm Rules --- */
.text-dim { color: var(--text-dim); }

/* generic inline form row (does NOT use .field's fixed 120px label) */
.ev-row {
  display: flex; align-items: center; gap: 10px;
  margin: 8px 0; flex-wrap: wrap;
}
.ev-row > label {
  color: var(--text-muted); font-size: 0.9em; display: inline-flex;
  align-items: center; gap: 6px;
}
.ev-row input, .ev-row select {
  padding: 0.45em; background: var(--bg-card); border: 1px solid var(--border-strong);
  border-radius: 8px; color: var(--text); font-size: 0.9em;
}
.ev-row input:focus, .ev-row select:focus { outline: none; border-color: var(--brand); }
.ev-row input[type="text"], .ev-row select { min-width: 170px; }
.ev-row input[type="number"] { width: 90px; }
.ev-row input.grow { flex: 1; min-width: 180px; }
.ev-row input[type="checkbox"] { width: auto; min-width: 0; accent-color: var(--brand); }

/* rule list rows */
.rule-row {
  display: flex; align-items: center; gap: 10px;
  padding: 8px 12px; margin: 6px 0;
  background: var(--bg-input); border: 1px solid var(--border); border-radius: 8px;
}
.rule-row .r-txt { flex: 1; min-width: 0; }
.rule-row .r-txt small { margin-left: 8px; }
.rule-row .sw { flex: 0 0 auto; }

/* THEN action rows: fixed-width type select, params take the rest */
.act-row {
  display: flex; align-items: center; gap: 8px;
  margin: 6px 0; flex-wrap: wrap;
}
.act-row select.a-type { flex: 0 0 200px; }
.act-row .a-params { display: flex; align-items: center; gap: 10px; flex: 1; flex-wrap: wrap; }
.act-row .a-del { flex: 0 0 auto; }
.ar-p { font-size: 0.85em; color: var(--text-muted); display: inline-flex; align-items: center; gap: 6px; }
.ar-p input { width: 100px; }
.ar-p select {
  padding: 0.35em; background: var(--bg-card); border: 1px solid var(--border-strong);
  border-radius: 8px; color: var(--text); font-size: 0.95em; min-width: 130px;
}

#editor details.adv { margin: 6px 0; }
#editor details.adv > summary {
  cursor: pointer; color: var(--text-dim); font-size: 0.85em; width: fit-content;
}
.ev-row label.cond { color: var(--text-muted); font-size: 0.9em; }

/* event log table */
table.tbl { width: 100%; border-collapse: collapse; margin-top: 10px; }
table.tbl th, table.tbl td {
  text-align: left; padding: 6px 8px; border-bottom: 1px solid var(--border); font-size: 0.9em;
}
table.tbl th { color: var(--text-dim); font-weight: normal; }

/* --- Auth overlay (401 → sign in) --- */
.auth-overlay {
  position: fixed;
  inset: 0;
  z-index: 9000;
  background: linear-gradient(160deg, #04245c 0%, #0a1226 100%);
  display: flex;
  align-items: center;
  justify-content: center;
}
.auth-card {
  background: var(--bg-card);
  border-radius: 18px;
  padding: 2.5em;
  max-width: 420px;
  width: 90%;
  box-shadow: 0 24px 60px rgba(13, 22, 44, 0.35);
}
.auth-card__logo { height: 28px; margin-bottom: 1.4em; }
.auth-card h1 { font-size: 1.4em; margin-bottom: 0.3em; }
.auth-card__subtitle {
  color: var(--text-muted);
  font-size: 0.95em;
  line-height: 1.55;
  margin-bottom: 1.5em;
}
.auth-card__error {
  font-size: 0.85em;
  color: var(--err);
  min-height: 1.3em;
  margin: 0.1em 0 0.5em;
}

/* Header user chip + sign-out */
.user-menu {
  display: inline-flex;
  align-items: center;
  gap: 0.6em;
}
.user-menu.hidden { display: none; }
.user-menu__name {
  font-size: 0.85em;
  font-weight: 600;
  color: var(--text-muted);
}

/* --- Confirm modal --- */
.modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 8000;
  background: rgba(13, 22, 44, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1em;
}
.modal {
  background: var(--bg-card);
  border-radius: 14px;
  box-shadow: 0 24px 60px rgba(13, 22, 44, 0.3);
  padding: 1.6em 1.8em;
  max-width: 420px;
  width: 100%;
}
.modal__title { font-size: 1.05em; margin-bottom: 0.6em; }
.modal__body {
  font-size: 0.9em;
  color: var(--text-muted);
  line-height: 1.55;
  white-space: pre-line;
  margin-bottom: 1.4em;
}
.modal__actions {
  display: flex;
  justify-content: flex-end;
  gap: 0.8em;
}

/* --- Global API activity: top progress bar + guard double submits --- */
body.api-busy::after {
  content: '';
  position: fixed;
  top: 0; left: 0; right: 0;
  height: 3px;
  z-index: 9500;
  background: linear-gradient(90deg, var(--brand), var(--brand-green), var(--brand));
  background-size: 200% 100%;
  animation: api-busy-slide 1s linear infinite;
}
@keyframes api-busy-slide {
  from { background-position: 200% 0; }
  to { background-position: 0 0; }
}
body.api-busy .btn-primary,
body.api-busy .btn-danger {
  pointer-events: none;
  opacity: 0.65;
}

/* --- Inline validation --- */
input.invalid, select.invalid, textarea.invalid {
  border-color: var(--err) !important;
  box-shadow: 0 0 0 3px rgba(224, 49, 49, 0.12) !important;
}
.field-error {
  font-size: 0.78em;
  color: var(--err);
  margin: 0.25em 0 0.4em;
}
.form-grid .field-error {
  grid-column: 2;          /* stay under the input column */
  margin-top: -0.3em;
}
.field { flex-wrap: wrap; }
.field .field-error {
  flex-basis: 100%;
  margin-left: 120px;      /* align under the input (label width) */
}

/* --- Skeleton loading placeholders --- */
.skel-group {
  display: flex;
  flex-direction: column;
  gap: 0.7em;
  padding: 0.4em 0;
}
.skel {
  height: 0.95em;
  border-radius: 6px;
  background: linear-gradient(90deg,
    var(--bg-light) 25%, #f8fafd 40%, var(--bg-light) 60%);
  background-size: 300% 100%;
  animation: skel-shimmer 1.3s ease-in-out infinite;
}
.skel-row td { padding: 0.6em 0.8em; }
.skel-row .skel { width: 100%; }
@keyframes skel-shimmer {
  from { background-position: 100% 0; }
  to { background-position: -100% 0; }
}

/* --- Empty states --- */
.empty-state {
  text-align: center;
  padding: 2.2em 1em;
  color: var(--text-dim);
}
.empty-state svg {
  width: 40px;
  height: 40px;
  stroke: var(--border-strong);
  margin-bottom: 0.6em;
}
.empty-state p { font-size: 0.9em; line-height: 1.5; }

/* --- Accessibility --- */
button:focus-visible,
a:focus-visible,
select:focus-visible,
input:focus-visible,
[tabindex]:focus-visible {
  outline: 2px solid var(--brand);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* ── Security page: IP filter entry list ── */
.ipf-addrow { display: flex; gap: 0.5em; max-width: 440px; }
.ipf-addrow input { flex: 1; }
.ipf-list { list-style: none; margin: 0; padding: 0; max-width: 440px; }
.ipf-list li {
  display: flex; align-items: center; gap: 0.6em;
  padding: 0.4em 0.6em; border: 1px solid var(--border-strong);
  border-radius: 8px; margin-bottom: 0.4em; background: var(--bg-card);
}
.ipf-list li code { flex: 1; }
.ipf-you {
  font-size: 0.75em; color: var(--ok); background: var(--ok-bg);
  padding: 0.1em 0.5em; border-radius: 999px; font-weight: 600;
}
.ipf-del {
  border: none; background: none; color: var(--text-dim);
  font-size: 1.2em; line-height: 1; cursor: pointer; padding: 0 0.2em;
}
.ipf-del:hover { color: var(--err); }
.btn-link {
  border: none; background: none; color: var(--brand);
  text-decoration: underline; cursor: pointer; font-size: inherit; padding: 0;
}
#ipf-body.is-disabled { opacity: 0.45; pointer-events: none; }

/* ── WiFi page: scan list, signal bars, password row ── */
.wf-list {
  list-style: none; margin: 0; padding: 2px; max-width: 440px;
  /* A busy 2.4GHz band easily yields 20-30 networks: cap the list
   * at ~6 rows and scroll, so the page keeps its shape. */
  max-height: 300px; overflow-y: auto;
}
.wf-list li {
  display: flex; align-items: center; gap: 0.6em;
  padding: 0.4em 0.7em; border: 1px solid var(--border-strong);
  border-radius: 8px; margin-bottom: 0.4em; background: var(--bg-card);
  cursor: pointer;
}
.wf-list li:hover { border-color: var(--brand); }
.wf-list li.sel { border-color: var(--brand); box-shadow: 0 0 0 2px rgba(0, 48, 135, 0.12); }
.wf-ssid { flex: 1; font-weight: 500; }
.wf-bars { width: 16px; height: 13px; flex: none; }
.wf-bars rect { fill: var(--border-strong); }
.wf-bars rect.on { fill: var(--brand); }
.wf-lock { width: 14px; height: 14px; color: var(--text-dim); }
.wf-pwrow { display: flex; gap: 0.5em; max-width: 440px; }
.wf-pwrow input { flex: 1; }
/* Generic password field with a Show/Hide button (mqtt, add-user). */
.pw-row { display: flex; gap: 0.5em; max-width: 440px; }
.pw-row input { flex: 1; }
.pw-eye { white-space: nowrap; }
.wf-eye { white-space: nowrap; }

/* ── Image (ISP) page: preview + controls two-pane ── */
.isp-card { max-width: 1180px; }
.isp-layout { display: flex; gap: 1.2em; align-items: flex-start; }
.isp-preview {
  /* Clear the 60px sticky header, or scrolling tucks the top of the
   * video underneath it. */
  flex: 0 0 46%; position: sticky; top: calc(60px + 1em);
}
.isp-preview video {
  width: 100%; aspect-ratio: 16/9; background: #111;
  border-radius: 8px; display: block; object-fit: contain;
}
.isp-preview-bar {
  display: flex; justify-content: space-between;
  font-size: 0.85em; margin-top: 0.4em;
}
.isp-panel { flex: 1; min-width: 0; }
.isp-chips {
  display: flex; gap: 0.5em; align-items: center; flex-wrap: wrap;
  margin-bottom: 1em;
}
.isp-chip {
  border: 1px solid var(--border-strong); background: var(--bg-card);
  border-radius: 999px; padding: 0.3em 0.9em; cursor: pointer;
  font-size: 0.9em; color: var(--text);
}
.isp-chip:hover { border-color: var(--brand); }
.isp-chip.active {
  background: var(--brand); color: #fff; border-color: var(--brand);
}
@media (max-width: 900px) {
  .isp-layout { flex-direction: column; }
  .isp-preview { position: static; flex: none; width: 100%; }
}

/* ── Playback: content search (B3) ── */
.sc-row { display: flex; gap: 1em; align-items: center; flex-wrap: wrap; margin-bottom: 0.8em; }
.sc-classes { display: flex; gap: 0.4em; }
.sc-chip {
  border: 1px solid var(--border-strong); background: var(--bg-card);
  border-radius: 999px; padding: 0.3em 0.9em; cursor: pointer; font-size: 0.9em;
  color: var(--text);
}
.sc-chip:hover { border-color: var(--brand); }
.sc-chip.active { background: var(--brand); color: #fff; border-color: var(--brand); }
.sc-conf { display: flex; align-items: center; gap: 0.5em; font-size: 0.85em; color: var(--text-muted); }
.sc-range { display: flex; align-items: center; gap: 0.4em; font-size: 0.85em; color: var(--text-muted); }
.sc-range select { padding: 0.25em 0.4em; }
.sc-results { display: flex; flex-wrap: wrap; gap: 0.5em; align-items: flex-start; }
.sc-daygroup {
  flex-basis: 100%; margin: 0.6em 0 0.1em; font-size: 0.85em; font-weight: 600;
  color: var(--text-muted); border-bottom: 1px solid var(--border); padding-bottom: 0.2em;
}
.sc-daygroup:first-child { margin-top: 0; }
.sc-card {
  display: flex; flex-direction: column; align-items: flex-start; gap: 0.15em;
  border: 1px solid var(--border-strong); background: var(--bg-card);
  border-radius: 8px; padding: 0.5em; cursor: pointer; width: 120px;
}
.sc-card:hover { border-color: var(--brand); }
.sc-card.active { border-color: var(--brand); box-shadow: 0 0 0 2px rgba(0,48,135,0.12); }
.sc-card:disabled { opacity: 0.5; cursor: not-allowed; }
.sc-card-thumb { width: 100%; }
.sc-card-thumb img {
  width: 100%; aspect-ratio: 4 / 3; object-fit: cover;
  border-radius: 4px; background: var(--bg-muted); display: block;
}
.sc-card-thumb:empty { display: none; }
.sc-card-class { font-weight: 600; text-transform: capitalize; }
.sc-card-time { font-size: 0.8em; color: var(--text-muted); }
.sc-card-conf { font-size: 0.75em; color: var(--ok); font-weight: 600; }

/* Opsis Camera — Global Styles
 *
 * Unileap corporate theme: light professional UI aligned with www.unileap.ai
 * (navy #003087 primary, green #A4D233 accent, soft grey surfaces).
 */

* { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  /* Unileap brand palette */
  --brand: #003087;
  --brand-dark: #04245c;
  --brand-green: #A4D233;

  /* Surfaces */
  --bg-main: #f5f7fb;
  --bg-card: #ffffff;
  --bg-input: #f8fafd;
  --bg-light: #eef2f8;
  --border: #e7ebf2;
  --border-strong: #d9e0ec;

  /* Interactive (legacy names kept for page code) */
  --accent: #003087;
  --accent-hover: #04245c;
  --accent-soft: rgba(0, 48, 135, 0.08);

  /* Text (dim kept ≥4.5:1 on white for WCAG AA small text) */
  --text: #0e1626;
  --text-muted: #5b6678;
  --text-dim: #6d7789;

  /* Status */
  --ok: #2f9e44;
  --ok-bg: #e9f7ec;
  --err: #e03131;
  --err-bg: #fdecec;
  --warn: #e8940a;
  --warn-bg: #fff4e0;
  --danger: #e03131;
  --color-err: #e03131;

  --radius: 14px;
  --shadow: 0 1px 2px rgba(13, 22, 44, 0.05), 0 8px 24px rgba(13, 22, 44, 0.05);
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Noto Sans",
    "Noto Sans TC", Roboto, Arial, sans-serif;
  background: var(--bg-main);
  color: var(--text);
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
}

/* --- Header + Top Tabs --- */
header {
  background: var(--bg-card);
  padding: 0 1.5em;
  height: 60px;
  display: flex;
  align-items: center;
  gap: 2em;
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 100;
}

.brand {
  display: flex;
  align-items: center;
  gap: 0.9em;
  white-space: nowrap;
}
.brand__logo { height: 24px; display: block; }

header .status { font-size: 0.85em; font-weight: 600; color: var(--ok); margin-left: auto; }
header .status.is-off { color: var(--err); }

#top-tabs {
  display: flex;
  height: 100%;
  gap: 0;
}
#top-tabs a {
  display: flex;
  align-items: center;
  padding: 0 1.2em;
  color: var(--text-muted);
  text-decoration: none;
  font-size: 0.95em;
  font-weight: 600;
  border-bottom: 2px solid transparent;
  transition: color 0.2s, border-color 0.2s;
}
#top-tabs a:hover { color: var(--text); }
#top-tabs a.active {
  color: var(--brand);
  border-bottom-color: var(--brand);
}

/* --- Layout --- */
#layout {
  display: flex;
  min-height: calc(100vh - 60px);
  background: var(--bg-main);
}

/* Boxed shell on wide screens: header + sidebar + content form one centred
   frame (same idiom as unileap.ai's 1180px wrap), outer bg one step darker. */
@media (min-width: 1280px) {
  body { background: #e6eaf2; }
  header, #layout {
    max-width: 1240px;
    margin: 0 auto;
    border-left: 1px solid var(--border-strong);
    border-right: 1px solid var(--border-strong);
  }
}

/* --- Sidebar --- */
#sidebar {
  width: 200px;
  background: var(--bg-card);
  border-right: 1px solid var(--border);
  padding: 1em 0;
  flex-shrink: 0;
}
/* Section headers: Unileap "eyebrow" style — navy, uppercase, wide
   tracking — with a divider between groups for clear hierarchy. */
#sidebar .nav-section {
  margin-top: 0.9em;
  padding: 1em 1em 0.45em;
  font-size: 0.7em;
  font-weight: 800;
  color: var(--brand);
  text-transform: uppercase;
  letter-spacing: 0.14em;
  border-top: 1px solid var(--border);
}
#sidebar .nav-section:first-child {
  margin-top: 0;
  padding-top: 0.4em;
  border-top: none;
}
#sidebar a {
  display: flex;
  align-items: center;
  gap: 0.65em;
  padding: 0.45em 1em 0.45em 1.6em;
  color: var(--text-muted);
  text-decoration: none;
  font-size: 0.9em;
  border-left: 3px solid transparent;
}
#sidebar a svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  opacity: 0.75;
}
#sidebar a.active svg,
#sidebar a:hover svg { opacity: 1; }
#sidebar a:hover { color: var(--brand); background: rgba(0, 48, 135, 0.04); }
#sidebar a.active {
  color: var(--brand);
  font-weight: 600;
  background: var(--accent-soft);
  border-left-color: var(--brand);
}
#sidebar a.disabled {
  color: #b6bdc9;
  pointer-events: none;
}

/* --- Main content ---
 * Fills the space next to the sidebar; cards span it, individual
 * inputs are width-capped below so forms stay readable. */
#app {
  flex: 1;
  min-width: 0;
  padding: 1.5em 2em;
}

/* --- Card --- */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 1.5em;
  margin-bottom: 1.5em;
}
.card h2 {
  color: var(--brand);
  font-size: 1.1em;
  margin-bottom: 1em;
  border-bottom: 1px solid var(--border);
  padding-bottom: 0.5em;
}

/* --- Form fields --- */
.field {
  display: flex;
  align-items: center;
  margin-bottom: 0.8em;
}
.field label {
  width: 120px;
  font-size: 0.9em;
  color: var(--text-muted);
  flex-shrink: 0;
}
.field input, .field select {
  flex: 1;
  max-width: 440px;
  padding: 0.5em;
  background: var(--bg-card);
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  color: var(--text);
  font-size: 0.9em;
}
.field input:focus, .field select:focus {
  outline: none;
  border-color: var(--brand);
  box-shadow: 0 0 0 3px rgba(0, 48, 135, 0.12);
}
.field input[readonly] {
  background: var(--bg-input);
  color: var(--text-muted);
}

/* --- Form grid (settings pages) --- */
.form-grid {
  display: grid;
  grid-template-columns: 140px 1fr;
  gap: 0.6em 1em;
  align-items: center;
  margin-bottom: 1em;
}
.form-grid label { font-size: 0.9em; color: var(--text-muted); }
.form-grid input, .form-grid select, .form-grid textarea {
  max-width: 440px;
  padding: 0.5em;
  background: var(--bg-card);
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  color: var(--text);
  font-size: 0.9em;
}
/* Denser variant for settings forms: labels never wrap, controls don't
 * stretch across the card. */
.form-grid--compact { grid-template-columns: 170px minmax(200px, 340px); }
.form-grid input:focus, .form-grid select:focus, .form-grid textarea:focus {
  outline: none;
  border-color: var(--brand);
  box-shadow: 0 0 0 3px rgba(0, 48, 135, 0.12);
}

/* --- Toggle switch --- */
.toggle {
  display: flex;
  align-items: center;
  gap: 0.6em;
  cursor: pointer;
}
.toggle input[type="checkbox"] {
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
  box-sizing: border-box;
  margin: 0;
  width: 40px;
  height: 22px;
  min-width: 40px;
  background: var(--border-strong);
  border: none;
  border-radius: 11px;
  position: relative;
  cursor: pointer;
  transition: background 0.2s;
  flex-shrink: 0;
  vertical-align: middle;
}
.toggle input[type="checkbox"]::after {
  content: '';
  position: absolute;
  top: 50%;
  margin-top: -8px;        /* half the knob height: vertical centre */
  left: 3px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 1px 3px rgba(13, 22, 44, 0.25);
  transition: left 0.2s, background 0.2s;
}
.toggle input[type="checkbox"]:checked {
  background: var(--brand);
}
.toggle input[type="checkbox"]:checked::after {
  left: 21px;              /* 40 - 16 - 3 = right margin 3px */
  background: #fff;
}
.toggle-label {
  font-size: 0.85em;
  color: var(--text-muted);
}

.form-note {
  font-size: 0.82em;
  color: var(--text-dim);
  margin: -0.3em 0 1em;
  line-height: 1.45;
}
.form-note a {
  color: var(--brand);
  font-weight: 600;
}

/* --- Card description (subtitle under h2) --- */
.hint {
  font-size: 0.88em;
  color: var(--text-muted);
  line-height: 1.55;
  margin: -0.4em 0 1.1em;
}

/* --- Info callout (cross-feature tips, notices) --- */
.callout {
  display: flex;
  align-items: flex-start;
  gap: 0.6em;
  font-size: 0.85em;
  color: var(--brand-dark);
  background: var(--accent-soft);
  border: 1px solid rgba(0, 48, 135, 0.18);
  border-radius: 8px;
  padding: 0.7em 0.9em;
  margin-bottom: 1.1em;
  line-height: 1.5;
}
.callout svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  margin-top: 0.15em;
  stroke: var(--brand);
}
.callout a {
  color: var(--brand);
  font-weight: 600;
}

/* Warning variant: consequence/risk notices (vs neutral info) */
.callout--warn {
  color: #7a4b00;
  background: var(--warn-bg);
  border-color: rgba(232, 148, 10, 0.5);
}
.callout--warn svg { stroke: #b26a00; }

/* --- Form static (read-only) --- */
.status-ok { color: var(--ok); font-weight: 600; }
.status-err { color: var(--err); font-weight: 600; }

.form-static {
  font-size: 0.9em;
  color: var(--text);
  padding: 0.5em 0;
}

/* --- Form actions --- */
.form-actions {
  display: flex;
  gap: 0.8em;
  margin-top: 1.2em;
  padding-top: 1em;
  border-top: 1px solid var(--border);
}

/* --- Image (ISP) page: slider rows, advanced disclosure --- */
.slider-row {
  display: flex;
  align-items: center;
  gap: 0.8em;
}
.slider-row input[type="range"] {
  flex: 1;
  padding: 0;
  background: transparent;
  border: none;
}
.slider-row output {
  min-width: 2.5em;
  text-align: right;
  font-size: 0.9em;
  color: var(--text-muted);
}
.form-grid input[type="checkbox"] {
  width: 1.1em;
  height: 1.1em;
  padding: 0;
  justify-self: start;
  accent-color: var(--brand);
}
details.advanced {
  margin-top: 1em;
  border-top: 1px solid var(--border);
  padding-top: 0.6em;
}
details.advanced > summary {
  cursor: pointer;
  font-weight: 600;
  margin-bottom: 0.6em;
}
p.muted {
  color: var(--text-muted);
  font-size: 0.85em;
  margin-top: 0.8em;
}
span.muted {
  color: var(--text-muted);
  font-size: 0.85em;
}
/* Locked recordings (playback list): protected from circular overwrite */
tr.rec-locked td { background: color-mix(in srgb, var(--brand) 6%, transparent); }

/* Storage volume cards (Storage → Management) */
.vol-card {
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.7em 0.9em;
  margin-bottom: 0.7em;
}
.vol-card__head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 0.6em;
  margin-bottom: 0.5em;
}
.vol-card__meta { margin-top: 0.4em; }
.vol-health--bad { color: var(--err, #d33); font-size: 0.85em; }
.vol-health--ok { color: var(--ok, #2f9e44); font-size: 0.85em; }
.vol-card__tools { margin-left: auto; display: inline-flex; gap: 6px; }
.vol-card--warn {
  border-color: var(--warn, #e8940a);
  background: color-mix(in srgb, #e8940a 8%, transparent);
}

/* Event recording window widget (Storage → Management): the bar mirrors
 * the pre/post sliders so the numbers have a picture. */
.ev-rec {
  border-top: 1px solid var(--border);
  margin-top: 1em;
  padding-top: 0.8em;
}
.ev-rec__title { margin: 0 0 0.3em; font-size: 1em; }
.ev-bar {
  display: flex;
  align-items: stretch;
  height: 26px;
  border-radius: 6px;
  overflow: hidden;
  border: 1px solid var(--border);
  margin: 6px 0 10px;
}
.ev-bar__pre, .ev-bar__post {
  flex-grow: 1;
  flex-basis: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.72em;
  color: var(--text-muted);
  transition: flex-grow 0.1s;
  min-width: 20px;
}
.ev-bar__pre { background: color-mix(in srgb, var(--brand) 18%, transparent); }
.ev-bar__post { background: color-mix(in srgb, #2f9e44 18%, transparent); }
.ev-bar__mark {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  padding: 0 4px;
  background: var(--warn, #e8940a);
  color: #fff;
  font-size: 0.8em;
}
.ev-rec__sliders {
  display: flex;
  flex-wrap: wrap;
  gap: 1.2em;
  align-items: center;
}
.ev-rec__sliders label {
  display: flex;
  align-items: center;
  gap: 0.5em;
  font-size: 0.9em;
}
.ev-rec__sliders input[type="range"] { width: 140px; }
.ev-rec__val { min-width: 2.5em; text-align: right; color: var(--text-muted); }

/* Disk recycling watermark bar: zones sized by the three thresholds */
.wm-bar {
  display: flex;
  align-items: stretch;
  height: 26px;
  border-radius: 6px;
  overflow: hidden;
  border: 1px solid var(--border);
  margin: 6px 0 10px;
  transition: opacity 0.15s;
}
.wm-bar__seg {
  flex-grow: 1;
  flex-basis: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.72em;
  color: var(--text-muted);
  transition: flex-grow 0.1s;
  min-width: 4px;
}
.wm-bar__ok      { background: color-mix(in srgb, #2f9e44 16%, transparent); }
.wm-bar__band    { background: color-mix(in srgb, #e8c40a 20%, transparent); }
.wm-bar__recycle { background: color-mix(in srgb, var(--warn, #e8940a) 30%, transparent); }
.wm-bar__stop    { background: color-mix(in srgb, #d33 35%, transparent); }
.wm-bar__dead    { background: color-mix(in srgb, var(--text-muted, #888) 18%, transparent); }

/* Threshold ticks under the bar and a live usage marker on it: the bar,
 * the numbers and the sliders share one color per boundary. */
.wm-bar--linked { position: relative; margin-bottom: 24px; overflow: visible; }
.wm-bar--linked .wm-bar__seg:first-child { border-radius: 6px 0 0 6px; }
.wm-bar--linked .wm-bar__seg--last { border-radius: 0 6px 6px 0; }
.wm-bar__tick {
  position: absolute;
  top: calc(100% + 2px);
  transform: translateX(-50%);
  font-size: 0.72em;
  font-weight: 600;
}
.wm-bar__now {
  position: absolute;
  top: -3px;
  bottom: -3px;
  width: 2px;
  background: var(--text);
  opacity: 0.75;
}
.wm-bar__now span {
  position: absolute;
  left: 4px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 0.72em;
  font-weight: 600;
  color: var(--text);
  white-space: nowrap;
}
.wm-dot {
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  margin-right: 4px;
  vertical-align: baseline;
}
#cfg-low      { accent-color: #cfa50a; }
#cfg-high     { accent-color: var(--warn, #e8940a); }
#cfg-critical { accent-color: #d33; }
#cfg-pre      { accent-color: var(--brand, #003087); }
#cfg-post     { accent-color: #2f9e44; }
#cfg-retention-event { accent-color: var(--brand, #003087); }

/* Inline note inside a rule action's parameter row (record: pre/post hint) */
.ar-note {
  display: block;
  width: 100%;
  font-size: 0.8em;
  margin-bottom: 2px;
}

/* --- Range slider --- */
.range-group {
  display: flex;
  align-items: center;
  gap: 0.8em;
}
.range-group input[type="range"] {
  flex: 1;
  appearance: none;
  height: 6px;
  background: var(--border-strong);
  border-radius: 3px;
  outline: none;
}
.range-group input[type="range"]::-webkit-slider-thumb {
  appearance: none;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--brand);
  cursor: pointer;
}
.range-group span {
  min-width: 2em;
  text-align: right;
  font-size: 0.9em;
  color: var(--text);
  font-weight: bold;
}

/* --- Fieldset sub-sections (settings groups) --- */
.card fieldset {
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 1.1em 1.2em 0.9em;
  margin: 1.6em 0;
  min-width: 0;
}
.card fieldset > .field:last-child,
.card fieldset > .ev-row:last-child { margin-bottom: 0.2em; }
.card legend {
  font-size: 0.75em;
  font-weight: 800;
  color: var(--brand);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  padding: 0 0.6em;
}

/* --- Section header inside card --- */
.card h3 {
  font-size: 0.95em;
  color: var(--text);
  margin: 1.2em 0 0.6em;
  padding-bottom: 0.3em;
  border-bottom: 1px solid var(--border);
}
.card h3:first-of-type {
  margin-top: 0;
}

/* --- Coming soon badge --- */
.badge-coming-soon {
  font-size: 0.75em;
  font-weight: normal;
  color: var(--text-dim);
  background: var(--bg-light);
  padding: 0.15em 0.5em;
  border-radius: 4px;
  margin-left: 0.5em;
  vertical-align: middle;
}

/* --- Disabled toggle --- */
.toggle--disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.toggle--disabled input[type="checkbox"] {
  cursor: not-allowed;
}

/* --- Stream URLs (RTSP) --- */
.card__footer {
  margin-top: 1.5em;
  padding-top: 1em;
  border-top: 1px solid var(--border);
}
.stream-urls {
  font-size: 0.85em;
  color: var(--text-muted);
  line-height: 1.8;
}
.stream-urls code {
  background: var(--bg-light);
  padding: 0.2em 0.5em;
  border-radius: 4px;
  font-family: 'SF Mono', monospace;
  color: var(--brand);
  font-size: 0.9em;
}

/* --- Buttons --- */
.actions {
  display: flex;
  gap: 0.8em;
  margin-top: 1.2em;
}
button {
  padding: 0.6em 1.5em;
  border: 1px solid transparent;
  border-radius: 999px;
  cursor: pointer;
  font-size: 0.9em;
  font-weight: 600;
  transition: background 0.18s, border-color 0.18s, color 0.18s;
}
.btn-primary {
  background: var(--brand);
  color: #fff;
  font-weight: 700;
}
.btn-primary:hover { background: var(--brand-dark); }
.btn-secondary {
  background: var(--bg-card);
  border-color: var(--border-strong);
  color: var(--text);
}
.btn-secondary:hover { border-color: var(--brand); color: var(--brand); }
.btn-danger {
  background: var(--err);
  color: #fff;
  font-weight: 700;
}
.btn-danger:hover { background: #c22525; }

/* Disabled buttons read as disabled regardless of variant — a solid
 * red Delete that does nothing (last-admin guard) must not look live. */
button:disabled,
.btn-primary:disabled, .btn-secondary:disabled, .btn-danger:disabled,
.btn-small:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  filter: grayscale(0.35);
}
button:disabled:hover,
.btn-danger:disabled:hover { background: var(--err); }
.btn-primary:disabled:hover { background: var(--brand); }

/* --- Info table --- */
.info-table {
  width: 100%;
  border-collapse: collapse;
}
.info-table td {
  padding: 0.4em 0;
  font-size: 0.9em;
}
.info-table td:first-child {
  color: var(--text-muted);
  width: 140px;
}

/* --- Toast notifications --- */
#toast-container {
  position: fixed;
  top: 1em;
  right: 1em;
  z-index: 1000;
  display: flex;
  flex-direction: column;
  gap: 0.5em;
}
.toast {
  padding: 0.6em 1.2em;
  border-radius: 8px;
  font-size: 0.85em;
  font-weight: 600;
  border: 1px solid transparent;
  box-shadow: var(--shadow);
  animation: toast-in 0.3s ease;
}
.toast.ok { background: var(--ok-bg); color: #23763a; border-color: rgba(47, 158, 68, 0.35); }
.toast.err { background: var(--err-bg); color: #b02525; border-color: rgba(224, 49, 49, 0.35); }
.toast.warn { background: var(--warn-bg); color: #9a6700; border-color: rgba(232, 148, 10, 0.4); }

@keyframes toast-in {
  from { opacity: 0; transform: translateX(1em); }
  to { opacity: 1; transform: translateX(0); }
}

/* --- Layout mode: live (no sidebar, centred player column) --- */
#layout.layout--live #sidebar { display: none; }
#layout.layout--live #app {
  max-width: 1080px;
  margin: 0 auto;
}

/* Player card (wren-pvm style): topbar + video stage + control strip
   presented as one contained card. */
.lv-player {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  overflow: hidden;
}
.lv-player:fullscreen {
  display: flex;
  flex-direction: column;
  border: none;
  border-radius: 0;
  background: #000;
}
.lv-player:fullscreen .lv-body { flex: 1; min-height: 0; }
.lv-player:fullscreen .lv-stage { aspect-ratio: auto; }

/* ── Top bar: camera name + stream selector + connection badge ── */
.lv-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1em;
  padding: 0.55em 1em;
  background: var(--bg-card);
  border-bottom: 1px solid var(--border);
  flex-shrink: 0;
}
.lv-topbar__left,
.lv-topbar__right { display: flex; align-items: center; gap: 0.75em; position: relative; }

/* Detection overlay filter popover */
.lv-detect-pop {
	position: absolute;
	top: calc(100% + 0.5em);
	right: 2.6em;
	z-index: 30;
	min-width: 15em;
	background: #fff;
	border: 1px solid var(--border, #d8dee6);
	border-radius: 8px;
	box-shadow: 0 6px 24px rgba(16, 34, 60, 0.14);
	padding: 0.6em 0.85em;
	text-align: left;
}
.lv-dtp__row {
	display: flex;
	align-items: center;
	gap: 0.5em;
	padding: 0.28em 0;
	font-size: 0.86em;
	cursor: pointer;
	white-space: nowrap;
}
.lv-dtp__master { font-weight: 600; }
.lv-dtp__sep { border-top: 1px solid var(--border, #e3e8ef); margin: 0.35em 0; }
.lv-dtp__swatch {
	display: inline-block;
	width: 0.85em;
	height: 0.85em;
	border-radius: 2px;
	border: 2px solid;
	flex: none;
}
.lv-dtp__swatch--motion { border-color: #d9b512; border-style: dashed; }
.lv-dtp__swatch--person { border-color: #7fa823; }
.lv-dtp__swatch--vehicle { border-color: #e08a2e; }
.lv-dtp__swatch--animal { border-color: #c084fc; }
.lv-dtp__swatch--object { border-color: #4aa3ff; }
.lv-dtp__conf { justify-content: space-between; margin-top: 0.2em; }
.lv-dtp__conf select { font-size: 1em; padding: 0.1em 0.3em; }
.lv-dtp__hint {
	margin: 0.5em 0 0;
	font-size: 0.75em;
	color: var(--text-dim, #7a8699);
	white-space: normal;
}

/* Small dot on the detect button when a display filter is active */
.btn-icon.is-filtered::after {
	content: '';
	position: absolute;
	top: 0.28em;
	right: 0.28em;
	width: 0.45em;
	height: 0.45em;
	border-radius: 50%;
	background: var(--accent, #a4d233);
}
.btn-icon { position: relative; }

.lv-streamicon { display: inline-flex; align-items: center; color: var(--brand); }
.lv-streamicon svg { width: 18px; height: 18px; }

.stream-select {
  padding: 0.35em 0.7em;
  background: var(--bg-card);
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  color: var(--text);
  font-size: 0.85em;
}
.stream-select:focus { outline: none; border-color: var(--brand); }

/* Connection badge */
.lv-badge {
  display: inline-flex; align-items: center; gap: 0.4em;
  font-size: 0.72em; font-weight: 600; letter-spacing: 0.05em; text-transform: uppercase;
  color: var(--text-dim); background: var(--bg-light);
  padding: 0.32em 0.65em; border-radius: 999px; border: 1px solid var(--border);
}
.lv-badge .lv-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--text-dim); }
.live-view.is-live .lv-badge { color: var(--ok); border-color: rgba(47,158,68,0.4); background: var(--ok-bg); }
.live-view.is-live .lv-badge .lv-dot {
  background: var(--ok); animation: lv-pulse-ok 1.6s infinite;
}

.btn-icon {
  background: var(--bg-card); border: 1px solid var(--border-strong); border-radius: 8px;
  color: var(--text); padding: 0.35em 0.55em; font-size: 1.05em; cursor: pointer;
  line-height: 1; display: inline-flex; align-items: center;
}
.btn-icon svg { width: 16px; height: 16px; }
.btn-icon:hover { background: var(--accent-soft); border-color: var(--brand); color: var(--brand); }

/* ── Player body: video stage + collapsible PTZ drawer ── */
.lv-body { display: flex; align-items: stretch; }

.lv-ptzpanel {
  width: 0;
  overflow: hidden;
  flex-shrink: 0;
  background: var(--bg-card);
  border-left: 0 solid var(--border);
  transition: width 0.25s ease, border-left-width 0.25s ease;
}
.live-view.is-ptz-open .lv-ptzpanel {
  width: 216px;
  border-left-width: 1px;
}
.lv-ptzpanel__inner {
  width: 216px;               /* fixed: content keeps shape while sliding */
  padding: 1.1em 1em;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.1em;
}
.lv-ptzpanel__inner .lv-card__title { align-self: flex-start; margin-bottom: 0; }

.btn-icon.active {
  background: var(--accent-soft);
  border-color: var(--brand);
  color: var(--brand);
}

/* ── Video stage: fixed 16:9 area inside the player card ── */
.lv-stage {
  flex: 1;
  position: relative;
  aspect-ratio: 16 / 9;
  background: #000;
  min-width: 0;
  overflow: hidden;
}
.lv-stage video,
.lv-stage img {
  position: absolute; inset: 0;
  width: 100%; height: 100%; object-fit: contain;
}

/* Idle state: big circular play button in the middle (wren-pvm style). */
.lv-empty {
  position: absolute; inset: 0; z-index: 1;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1em;
  text-align: center; padding: 1em;
  background: radial-gradient(ellipse at center, #10182b 0%, #000 75%);
  cursor: pointer;
}
.lv-bigplay {
  width: 84px; height: 84px; border-radius: 50%;
  border: 4px solid rgba(255, 255, 255, 0.5);
  display: flex; align-items: center; justify-content: center;
  transition: border-color 0.25s, transform 0.25s;
}
.lv-bigplay svg {
  width: 34px; height: 34px; margin-left: 4px;
  fill: rgba(255, 255, 255, 0.65);
  transition: fill 0.25s;
}
.lv-empty:hover .lv-bigplay { border-color: rgba(255, 255, 255, 0.9); transform: scale(1.05); }
.lv-empty:hover .lv-bigplay svg { fill: rgba(255, 255, 255, 0.95); }
.lv-empty__hint { font-size: 0.85em; color: #8b95a7; }
.live-view.is-live .lv-empty { display: none; }

/* Video overlays */
.lv-overlay { position: absolute; z-index: 2; pointer-events: none; }
.lv-detect-canvas {
	position: absolute;
	inset: 0;
	width: 100%;
	height: 100%;
	z-index: 2;
	pointer-events: none;
}
/* Top-right, not top-left: the camera's own OSD (name and timestamp) is
 * burned into the top-left of the encoded frame, so a badge there covers
 * it. See osd_control.c OSD_POS_X/OSD_POS_Y. */
.lv-overlay--tr { top: 0.7em; right: 0.7em; }
.lv-overlay--bl { left: 0.7em; bottom: 0.7em; }

.lv-live {
  display: none; align-items: center; gap: 0.4em;
  font-size: 0.72em; font-weight: 700; letter-spacing: 0.08em; color: #fff;
  background: rgba(224,49,49,0.92); padding: 0.28em 0.6em; border-radius: 4px;
}
.lv-rec[hidden] { display: none; }
.lv-rec {
	display: inline-flex;
	align-items: center;
	gap: 0.35em;
	margin-left: 0.6em;
	padding: 0.15em 0.55em;
	border-radius: 4px;
	background: rgba(0, 0, 0, 0.55);
	color: #ff4d4d;
	font-size: 0.72em;
	font-weight: 700;
	letter-spacing: 0.08em;
}
.lv-rec__dot {
	width: 0.6em;
	height: 0.6em;
	border-radius: 50%;
	background: #ff4d4d;
	animation: lv-rec-blink 1.2s infinite;
}
@keyframes lv-rec-blink {
	50% { opacity: 0.25; }
}

.lv-live__dot { width: 7px; height: 7px; border-radius: 50%; background: #fff; animation: lv-pulse 1.4s infinite; }
.live-view.is-live .lv-live { display: inline-flex; }

.lv-osd {
  display: none; font-size: 0.75em; color: #fff; background: rgba(0,0,0,0.55);
  padding: 0.28em 0.6em; border-radius: 4px; font-variant-numeric: tabular-nums;
}
.live-view.is-live .lv-osd { display: inline-block; }

@keyframes lv-pulse {
  0% { box-shadow: 0 0 0 0 rgba(224,49,49,0.6); }
  70% { box-shadow: 0 0 0 6px rgba(224,49,49,0); }
  100% { box-shadow: 0 0 0 0 rgba(224,49,49,0); }
}
@keyframes lv-pulse-ok {
  0% { box-shadow: 0 0 0 0 rgba(47,158,68,0.6); }
  70% { box-shadow: 0 0 0 5px rgba(47,158,68,0); }
  100% { box-shadow: 0 0 0 0 rgba(47,158,68,0); }
}

/* One-line stream summary in the topbar */
.lv-inforow {
  font-size: 0.8em;
  color: var(--text-dim);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.lv-card__title {
  font-size: 0.76em; font-weight: 700; text-transform: uppercase; letter-spacing: 0.07em;
  color: var(--brand); margin-bottom: 0.9em;
}

/* PTZ pad + zoom/focus groups (inside the drawer) */
.ptz-pad {
  display: grid;
  grid-template-columns: repeat(3, 48px);
  gap: 6px;
}
.ptz-pad button {
  aspect-ratio: 1; padding: 0; font-size: 1em;
  background: var(--bg-input); border: 1px solid var(--border-strong); border-radius: 10px;
  color: var(--text); cursor: pointer; display: flex; align-items: center; justify-content: center;
}
.ptz-pad button:hover { background: var(--accent-soft); border-color: var(--brand); color: var(--brand); }
.ptz-pad button[data-dir="home"] { background: var(--accent-soft); color: var(--brand); border-color: rgba(0, 48, 135, 0.25); }

.lv-ptz__group {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.6em;
}
.lv-ptz__label {
  font-size: 0.75em;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-dim);
}
.lv-ptz__btns { display: flex; gap: 6px; }
.lv-ptz__btns button {
  width: 42px; height: 36px; padding: 0; font-size: 0.95em;
  background: var(--bg-input); border: 1px solid var(--border-strong); border-radius: 10px;
  color: var(--text); cursor: pointer;
}
.lv-ptz__btns button:hover { background: var(--accent-soft); border-color: var(--brand); color: var(--brand); }

/* ── Control strip attached under the video (icon buttons) ── */
.lv-controls {
  display: flex; align-items: center; justify-content: space-between; gap: 1em;
  padding: 0.35em 0.7em;
  background: var(--bg-card); border-top: 1px solid var(--border);
}
.lv-controls__left { display: flex; align-items: center; gap: 0.25em; }
.lv-controls__right {
  display: flex; align-items: center; gap: 0.6em;
  font-size: 0.82em; color: var(--text-dim);
  font-variant-numeric: tabular-nums; white-space: nowrap;
}
.lvc-btn {
  display: inline-flex; align-items: center; justify-content: center;
  width: 38px; height: 34px; padding: 0;
  background: transparent; border: none; border-radius: 8px;
  color: var(--text-muted); cursor: pointer;
}
.lvc-btn svg { width: 18px; height: 18px; }
.lvc-btn span { display: none; }   /* icon-only; labels stay for a11y/JS */
.lvc-btn:hover:not([disabled]) { background: var(--accent-soft); color: var(--brand); }
.lvc-btn[disabled] { opacity: 0.35; cursor: default; }
.lv-player:fullscreen .lv-controls { border-top-color: #1c2333; background: #0a0f1c; }
.lv-player:fullscreen .lvc-btn { color: #aeb7c6; }

/* Push-to-talk: highlight while transmitting (hold to talk). */
#btn-talk { touch-action: none; user-select: none; }
#btn-talk.is-talking {
  background: var(--danger, #e03131); border-color: var(--danger, #e03131); color: #fff;
  animation: lv-pulse 1.2s infinite;
}
#btn-talk.is-talking svg { stroke: #fff; }

/* Narrow screens: drop the inline stream summary (badge stays) */
@media (max-width: 760px) {
  .lv-inforow { display: none; }
}

/* Touch devices: grow interactive targets to >=44px (WCAG 2.5.8) */
@media (pointer: coarse) {
  .lvc-btn { width: 48px; height: 44px; }
  .lvc-btn svg { width: 20px; height: 20px; }
  .btn-icon { padding: 0.6em 0.8em; }
  .ptz-pad { grid-template-columns: repeat(3, 52px); }
  .lv-ptz__btns button { width: 48px; height: 44px; }
}

/* --- Dashboard --- */

/* Gauge row */
.gauge-row {
  display: flex;
  gap: 2em;
  justify-content: center;
  flex-wrap: wrap;
}

.gauge {
  text-align: center;
  min-width: 100px;
}

.gauge__circle {
  width: 90px;
  height: 90px;
  border-radius: 50%;
  background: conic-gradient(
    var(--ok) calc(var(--pct) * 1%),
    var(--bg-light) 0
  );
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 0.4em;
  position: relative;
}
.gauge--warn .gauge__circle {
  background: conic-gradient(
    var(--warn) calc(var(--pct) * 1%),
    var(--bg-light) 0
  );
}
.gauge--err .gauge__circle {
  background: conic-gradient(
    var(--err) calc(var(--pct) * 1%),
    var(--bg-light) 0
  );
}

.gauge__circle::after {
  content: '';
  position: absolute;
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: var(--bg-card);
}

.gauge__value {
  position: relative;
  z-index: 1;
  font-size: 1.1em;
  font-weight: bold;
  color: var(--text);
}

.gauge__label {
  font-size: 0.85em;
  color: var(--text-muted);
}

.gauge__detail {
  font-size: 0.75em;
  color: var(--text-dim);
  margin-top: 0.2em;
}

.dashboard__uptime {
  text-align: center;
  margin-top: 1em;
  font-size: 0.85em;
  color: var(--text-dim);
}

/* Topology */
.topo {
  overflow-x: auto;
  padding: 0.5em 0;
}

.topo__svg {
  width: 100%;
  min-width: 500px;
  height: auto;
}

.topo__node:hover rect {
  stroke-width: 3;
  filter: brightness(1.05);
}

.topo__legend {
  display: flex;
  gap: 1.2em;
  justify-content: center;
  margin-top: 0.8em;
  font-size: 0.8em;
  color: var(--text-dim);
}

.topo__legend-item {
  display: flex;
  align-items: center;
  gap: 0.3em;
}

/* Daemon cards grid */
.daemon-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 1em;
}

.daemon-card {
  background: var(--bg-input);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.8em 1em;
  border-left: 3px solid var(--text-dim);
}
.daemon-card--running { border-left-color: var(--ok); }
.daemon-card--unresponsive { border-left-color: var(--warn); }
.daemon-card--stopped { border-left-color: var(--err); }
.daemon-card--static { border-left-color: var(--text-dim); }
.daemon-card--not_deployed { border-left-color: var(--text-dim); }

.daemon-card__name {
  font-weight: bold;
  font-size: 0.95em;
  margin-bottom: 0.2em;
}

.daemon-card__meta {
  font-size: 0.8em;
  color: var(--text-muted);
  margin-bottom: 0.5em;
}

.daemon-card__cat {
  color: var(--text-dim);
}

.daemon-card__stat {
  font-size: 0.8em;
  color: var(--text-muted);
  padding: 0.1em 0;
}

/* --- Daemon restart detection --- */
.daemon-card--restarted {
  animation: card-blink 0.6s ease 3;
}
@keyframes card-blink {
  0%, 100% { background: var(--bg-input); }
  50% { background: rgba(232, 148, 10, 0.2); }
}
.daemon-card__restart-badge {
  font-size: 0.7em;
  font-weight: normal;
  color: #9a6700;
  background: var(--warn-bg);
  padding: 0.1em 0.4em;
  border-radius: 3px;
  margin-left: 0.4em;
}

/* --- Responsive: tablet (<=768px) --- */
@media (max-width: 768px) {
  header { padding: 0 0.8em; gap: 0.5em; }
  .brand__logo { height: 20px; }

  #sidebar { width: 160px; }
  #sidebar a { padding: 0.4em 0.6em 0.4em 1em; font-size: 0.85em; }

  #app { padding: 1em; }

  .gauge-row { gap: 1em; }
  .gauge__circle { width: 72px; height: 72px; }
  .gauge__circle::after { width: 50px; height: 50px; }
  .gauge__value { font-size: 0.95em; }

  .daemon-grid {
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 0.6em;
  }

  .topo__svg { min-width: 400px; }


  .form-grid { grid-template-columns: 120px 1fr; gap: 0.5em 0.8em; }
}

/* --- Responsive: mobile (<=480px) --- */
@media (max-width: 480px) {
  /* Keep the Live View / Settings tabs — hiding them stranded phones on
   * whichever page they landed on. Compact them instead. */
  header { padding: 0 0.6em; gap: 0.8em; }
  #top-tabs { gap: 0.9em; flex: none; }
  #top-tabs a { padding: 0 0.15em; font-size: 0.9em; }
  header .user-menu__name { display: none; }  /* keep Online + logout only */

  #layout { flex-direction: column; }
  #sidebar {
    width: 100%;
    border-right: none;
    border-bottom: 1px solid var(--border);
    padding: 0.5em 0;
    overflow-x: auto;
    white-space: nowrap;
    display: flex;
    flex-wrap: nowrap;
  }
  #sidebar .nav-section { display: none; }
  #sidebar a {
    display: inline-flex;
    padding: 0.4em 0.8em;
    white-space: nowrap;
    border-left: none;
  }

  #app { padding: 0.8em; }
  .card { padding: 1em; margin-bottom: 1em; }
  .card h2 { font-size: 1em; }

  .gauge-row { gap: 0.8em; }
  .gauge__circle { width: 64px; height: 64px; }
  .gauge__circle::after { width: 44px; height: 44px; }
  .gauge__value { font-size: 0.85em; }

  .daemon-grid {
    grid-template-columns: 1fr;
    gap: 0.5em;
  }


  .topo__svg { min-width: 320px; }
  .topo__legend { flex-wrap: wrap; gap: 0.5em; font-size: 0.75em; }

  .form-grid { grid-template-columns: 1fr; gap: 0.4em; }
  .form-grid label { margin-top: 0.3em; }
}

/* --- Data table (user management etc.) --- */
.data-table {
  width: 100%;
  border-collapse: collapse;
}
.data-table thead th {
  text-align: left;
  font-size: 0.8em;
  color: var(--text-dim);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding: 0.5em 0.8em;
  border-bottom: 1px solid var(--border-strong);
}
.data-table tbody td {
  padding: 0.6em 0.8em;
  font-size: 0.9em;
  border-bottom: 1px solid var(--border);
}
.data-table tbody tr:hover {
  background: rgba(0, 48, 135, 0.03);
}
.data-table .empty-row td {
  color: var(--text-dim);
  text-align: center;
  padding: 1.5em;
}

/* --- Role badges --- */
.badge {
  display: inline-block;
  font-size: 0.78em;
  font-weight: 600;
  padding: 0.15em 0.55em;
  border-radius: 4px;
  text-transform: capitalize;
}
.badge-admin {
  color: #b02525;
  background: var(--err-bg);
}
.badge-operator {
  color: #9a6700;
  background: var(--warn-bg);
}
.badge-viewer {
  color: var(--brand);
  background: var(--accent-soft);
}

/* --- Small button --- */
.btn-small {
  padding: 0.3em 0.8em;
  font-size: 0.8em;
}

/* --- Form group / row (server settings) --- */
.form-group {
  margin-bottom: 0.8em;
}
.form-group label {
  display: block;
  font-size: 0.85em;
  color: var(--text-muted);
  margin-bottom: 0.3em;
}
.form-group input,
.form-group select {
  width: 100%;
  padding: 0.5em;
  background: var(--bg-card);
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  color: var(--text);
  font-size: 0.9em;
}
.form-group input:focus,
.form-group select:focus {
  outline: none;
  border-color: var(--brand);
  box-shadow: 0 0 0 3px rgba(0, 48, 135, 0.12);
}

.form-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1em;
  align-items: end;
}

@media (max-width: 480px) {
  .form-row { grid-template-columns: 1fr; }
}

/* --- System Log --- */

/* Output level bar */
.log-output-level {
  display: flex;
  align-items: center;
  gap: 0.8em;
  margin-bottom: 1.2em;
  padding: 0.8em 1em;
  background: var(--bg-input);
  border-radius: 8px;
  border: 1px solid var(--border);
}
.log-output-level__label {
  font-size: 0.85em;
  color: var(--text-muted);
  font-weight: 600;
  white-space: nowrap;
}

/* Filter bar */
.log-filters {
  display: flex;
  align-items: center;
  gap: 0.6em;
  margin-bottom: 1em;
  flex-wrap: wrap;
}

/* Shared select/input styling for log page */
.log-select {
  padding: 0.4em 0.6em;
  background: var(--bg-card);
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  color: var(--text);
  font-size: 0.85em;
}
.log-select:focus {
  outline: none;
  border-color: var(--brand);
}

.log-search {
  flex: 1;
  min-width: 140px;
  padding: 0.4em 0.6em;
  background: var(--bg-card);
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  color: var(--text);
  font-size: 0.85em;
}
.log-search:focus {
  outline: none;
  border-color: var(--brand);
}
.log-search::placeholder {
  color: var(--text-dim);
}

.log-auto-refresh {
  margin-left: auto;
  white-space: nowrap;
}

/* Table wrapper */
.log-table-wrap {
  overflow-x: auto;
  border: 1px solid var(--border);
  border-radius: 8px;
}

/* Log table — extends data-table */
.log-table {
  font-size: 0.85em;
}
.log-table thead th {
  position: sticky;
  top: 0;
  background: var(--bg-input);
  z-index: 1;
}
.log-table tbody tr:hover {
  background: rgba(0, 48, 135, 0.04);
}

/* Column widths */
.log-col-time {
  width: 130px;
  white-space: nowrap;
  font-family: 'SF Mono', 'Consolas', monospace;
  font-size: 0.92em;
}
.log-col-daemon {
  width: 90px;
  white-space: nowrap;
}
.log-col-level {
  width: 36px;
  text-align: center;
}
.log-col-msg {
  word-break: break-word;
  font-family: 'SF Mono', 'Consolas', monospace;
  font-size: 0.92em;
}

/* Level badges */
.log-badge {
  display: inline-block;
  width: 22px;
  height: 22px;
  line-height: 22px;
  text-align: center;
  border-radius: 4px;
  font-size: 0.8em;
  font-weight: 700;
}
.log-badge--error {
  color: #fff;
  background: var(--err);
}
.log-badge--warning {
  color: #8a5400;
  background: var(--warn-bg);
  border: 1px solid rgba(232, 148, 10, 0.5);
}
.log-badge--info {
  color: var(--text-muted);
  background: var(--bg-light);
}
.log-badge--debug {
  color: var(--text-dim);
  background: var(--bg-input);
}

/* Footer: pagination + actions */
.log-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 1em;
  flex-wrap: wrap;
  gap: 0.8em;
}

.log-pagination {
  display: flex;
  align-items: center;
  gap: 0.6em;
}

.log-page-info {
  font-size: 0.85em;
  color: var(--text-muted);
  min-width: 12em;
  text-align: center;
}

.log-actions {
  display: flex;
  gap: 0.6em;
}

/* Responsive */
@media (max-width: 768px) {
  .log-filters { gap: 0.4em; }
  .log-auto-refresh { margin-left: 0; }
  .log-col-daemon { display: none; }
  .log-col-time { width: 100px; font-size: 0.85em; }
}

@media (max-width: 480px) {
  .log-output-level { flex-wrap: wrap; }
  .log-footer { flex-direction: column; align-items: stretch; }
  .log-pagination { justify-content: center; }
  .log-actions { justify-content: center; }
}

/* --- Storage: Progress Bar --- */
.progress-bar { height: 12px; background: var(--bg-light); border-radius: 6px; overflow: hidden; }
.progress-fill { height: 100%; background: var(--brand); transition: width 0.3s, background 0.3s; }
.progress-fill--warn { background: var(--warn); }
.progress-fill--crit { background: var(--err); }

/* --- Storage: Schedule Grid --- */
.sched-toolbar { display: flex; gap: 16px; margin-bottom: 8px; }
.sched-toolbar label { display: flex; align-items: center; gap: 4px; cursor: pointer; }
.sched-legend { padding: 2px 8px; border-radius: 4px; font-size: 0.85em; }
.sched-off-label { background: var(--bg-light); }
.sched-cont-label { background: var(--brand); color: #fff; }
.sched-event-label { background: var(--ok); color: #fff; }

/* The chips ARE the selector: the picked brush is lit and ticked, the
 * rest dim — the native radio dot was far too easy to miss (looked like
 * "selecting Continuous does nothing"). */
.sched-toolbar input[type="radio"] {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}
.sched-toolbar .sched-legend { opacity: 0.45; transition: opacity 0.12s, box-shadow 0.12s; }
.sched-toolbar input:checked + .sched-legend {
  opacity: 1;
  box-shadow: 0 0 0 2px var(--bg-card), 0 0 0 4px var(--text);
}
.sched-toolbar input:checked + .sched-legend::before { content: "\2713 "; }
.sched-toolbar input:focus-visible + .sched-legend {
  outline: 2px solid var(--brand);
  outline-offset: 3px;
}

/* Snapshot gallery hour bar: one cell per hour, heat = photo count */
.sn-hourbar {
  display: flex;
  height: 26px;
  border: 1px solid var(--border);
  border-radius: 6px;
  overflow: hidden;
}
.sn-hourcell {
  flex: 1;
  padding: 0;
  border: none;
  border-right: 1px solid var(--border);
  background: var(--bg-light);
  cursor: pointer;
  position: relative;
}
.sn-hourcell:last-child { border-right: none; }
.sn-hourcell i { position: absolute; inset: 0; display: block; background: var(--brand); }
.sn-hourcell--empty { cursor: default; }
.sn-hourcell--empty i { display: none; }
.sn-hourcell:not([disabled]):hover { outline: 2px solid var(--warn, #e8940a); outline-offset: -2px; z-index: 1; }
.sn-hourcell.active { outline: 2px solid var(--text); outline-offset: -2px; z-index: 1; }
.sn-hourlabels {
  display: flex;
  justify-content: space-between;
  font-size: 0.72em;
  color: var(--text-muted);
  margin-top: 2px;
}

/* Snapshot gallery lightbox */
.sn-lightbox {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.85);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  cursor: zoom-out;
}
.sn-lightbox figure { margin: 0; max-width: 92vw; max-height: 92vh; text-align: center; }
.sn-lightbox img { max-width: 92vw; max-height: 84vh; border-radius: 6px; }
.sn-lightbox figcaption {
  color: #fff;
  margin-top: 8px;
  display: flex;
  gap: 12px;
  align-items: center;
  justify-content: center;
}

/* Playback: the player, timeline and list act as one unit */
.pb-player {
  display: block;
  width: 100%;
  height: 360px;          /* fixed stage: no layout jump on load/unload */
  background: #000;
  border-radius: 8px;
  object-fit: contain;    /* clips letterbox inside instead of resizing */
}
#rec-tbody tr[data-rec] { cursor: pointer; }
#rec-tbody tr[data-rec]:hover { background: color-mix(in srgb, var(--brand) 5%, transparent); }
#rec-tbody tr.rec-playing { background: color-mix(in srgb, var(--brand) 12%, transparent); }
.tl-seg.tl-playing { outline: 2px solid var(--text); outline-offset: 1px; z-index: 1; }
.tl-playhead {
  position: absolute;
  top: -3px;
  bottom: -3px;
  width: 2px;
  background: var(--err, #d33);
  box-shadow: 0 0 3px color-mix(in srgb, var(--err, #d33) 80%, transparent);
  z-index: 2;
  pointer-events: none;
}

.sched-grid { overflow-x: auto; }
/* Horizontal week grid: days as rows, half-hour slots as columns.
 * The whole week is visible at once — no vertical scrolling. */
.sched-h { border-collapse: collapse; font-size: 0.75em; user-select: none; }
.sched-h th { font-weight: 600; color: var(--text-muted); padding: 0 0 4px; text-align: left; }
.sched-h-day {
  font-weight: 600; color: var(--text-muted); padding-right: 8px;
  white-space: nowrap; text-align: right;
}
.sched-hc {
  width: 14px; min-width: 14px; height: 20px; cursor: pointer;
  border: 1px solid var(--border); background: var(--bg-light);
}
.sched-hc:hover { outline: 2px solid var(--brand); outline-offset: -1px; }
.sched-cont { background: var(--brand); }
.sched-event { background: var(--ok); }

/* --- Storage: Playback Layout --- */
.playback-layout { display: grid; grid-template-columns: 220px 1fr; gap: 16px; }
.playback-sidebar { position: sticky; top: 16px; align-self: start; }

/* Calendar */
.cal-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; }
.cal-header button { background: none; border: 1px solid var(--border-strong); color: var(--text); padding: 2px 8px; cursor: pointer; border-radius: 6px; }
.cal-grid { font-size: 0.85em; }
.cal-row { display: grid; grid-template-columns: repeat(7, 1fr); gap: 2px; }
.cal-cell { text-align: center; padding: 4px 0; border-radius: 6px; }
.cal-hdr { font-weight: bold; color: var(--text-dim); }
.cal-day { cursor: pointer; }
.cal-day:hover { background: var(--bg-light); }
.cal-has-rec { color: var(--brand); font-weight: bold; }
.cal-has-rec::after { content: ''; display: block; width: 4px; height: 4px; border-radius: 50%; background: var(--brand); margin: 1px auto 0; }
.cal-selected { background: var(--brand); color: #fff; font-weight: bold; }

/* Timeline */
.timeline { margin: 8px 0; }
/* M3.2: zoomable timeline — the inner track grows wider than the viewport
 * (100% / 400% / 2400%) and the wrap scrolls horizontally = panning. */
.tl-zoom { display: flex; gap: 6px; margin-bottom: 6px; }
.timeline-wrap { overflow-x: auto; padding-bottom: 4px; }
.tl-inner { min-width: 100%; }
.timeline-bar { position: relative; height: 24px; background: var(--bg-light); border-radius: 6px; cursor: crosshair; }
/* Export range selection: orange stripes so it reads against both the
 * navy continuous and green event segments (a flat brand-blue wash was
 * invisible on top of continuous footage). */
.tl-select {
  position: absolute;
  top: -3px;
  bottom: -3px;
  height: auto;
  background: repeating-linear-gradient(45deg,
    color-mix(in srgb, var(--warn, #e8940a) 55%, transparent) 0 6px,
    color-mix(in srgb, var(--warn, #e8940a) 20%, transparent) 6px 12px);
  border: 2px solid var(--warn, #e8940a);
  border-radius: 3px;
  z-index: 2;
  pointer-events: none;
}
#tl-export { display: flex; align-items: center; gap: 8px; margin-top: 6px; }
.tl-seg { position: absolute; top: 0; height: 100%; border-radius: 2px; opacity: 0.85; }
.tl-cont { background: var(--brand); }
/* AI detection markers overlaid on the timeline (B3 Phase 2) */
.tl-det { position: absolute; top: -3px; width: 4px; height: 30px; border-radius: 2px;
  transform: translateX(-2px); box-shadow: 0 0 0 1px var(--bg-card); }
.tl-det:hover { width: 6px; transform: translateX(-3px); z-index: 2; }
.tl-event { background: var(--ok); }
.timeline-labels { display: flex; justify-content: space-between; font-size: 0.75em; color: var(--text-dim); margin-top: 2px; }

/* Recording list badges */
.badge { padding: 2px 6px; border-radius: 4px; font-size: 0.8em; }
.badge-cont { background: var(--brand); color: #fff; }
.badge-event { background: var(--ok); color: #fff; }
.badge-manual { background: var(--warn-bg); color: #8a5400; border: 1px solid rgba(232, 148, 10, 0.5); }
.btn-sm { padding: 2px 8px; font-size: 0.8em; background: var(--bg-card); border: 1px solid var(--border-strong); color: var(--text); cursor: pointer; border-radius: 6px; text-decoration: none; }
.btn-sm:hover { background: var(--brand); border-color: var(--brand); color: #fff; }

@media (max-width: 768px) {
  .playback-layout { grid-template-columns: 1fr; }
  .playback-sidebar { position: static; }
}

/* --- Misc --- */
.info { font-size: 0.85em; color: var(--text-dim); }
.hidden { display: none; }

/* --- Event / Alarm Rules --- */
.text-dim { color: var(--text-dim); }

/* generic inline form row (does NOT use .field's fixed 120px label) */
.ev-row {
  display: flex; align-items: center; gap: 10px;
  margin: 8px 0; flex-wrap: wrap;
}
.ev-row > label {
  color: var(--text-muted); font-size: 0.9em; display: inline-flex;
  align-items: center; gap: 6px;
}
.ev-row input, .ev-row select {
  padding: 0.45em; background: var(--bg-card); border: 1px solid var(--border-strong);
  border-radius: 8px; color: var(--text); font-size: 0.9em;
}
.ev-row input:focus, .ev-row select:focus { outline: none; border-color: var(--brand); }
.ev-row input[type="text"], .ev-row select { min-width: 170px; }
.ev-row input[type="number"] { width: 90px; }
.ev-row input.grow { flex: 1; min-width: 180px; }
.ev-row input[type="checkbox"] { width: auto; min-width: 0; accent-color: var(--brand); }

/* rule list rows */
.rule-row {
  display: flex; align-items: center; gap: 10px;
  padding: 8px 12px; margin: 6px 0;
  background: var(--bg-input); border: 1px solid var(--border); border-radius: 8px;
}
.rule-row .r-txt { flex: 1; min-width: 0; }
.rule-row .r-txt small { margin-left: 8px; }
.rule-row .sw { flex: 0 0 auto; }

/* THEN action rows: fixed-width type select, params take the rest */
.act-row {
  display: flex; align-items: center; gap: 8px;
  margin: 6px 0; flex-wrap: wrap;
}
.act-row select.a-type { flex: 0 0 200px; }
.act-row .a-params { display: flex; align-items: center; gap: 10px; flex: 1; flex-wrap: wrap; }
.act-row .a-del { flex: 0 0 auto; }
.ar-p { font-size: 0.85em; color: var(--text-muted); display: inline-flex; align-items: center; gap: 6px; }
.ar-p input { width: 100px; }
.ar-p select {
  padding: 0.35em; background: var(--bg-card); border: 1px solid var(--border-strong);
  border-radius: 8px; color: var(--text); font-size: 0.95em; min-width: 130px;
}

#editor details.adv { margin: 6px 0; }
#editor details.adv > summary {
  cursor: pointer; color: var(--text-dim); font-size: 0.85em; width: fit-content;
}
.ev-row label.cond { color: var(--text-muted); font-size: 0.9em; }

/* event log table */
table.tbl { width: 100%; border-collapse: collapse; margin-top: 10px; }
table.tbl th, table.tbl td {
  text-align: left; padding: 6px 8px; border-bottom: 1px solid var(--border); font-size: 0.9em;
}
table.tbl th { color: var(--text-dim); font-weight: normal; }

/* --- Auth overlay (401 → sign in) --- */
.auth-overlay {
  position: fixed;
  inset: 0;
  z-index: 9000;
  background: linear-gradient(160deg, #04245c 0%, #0a1226 100%);
  display: flex;
  align-items: center;
  justify-content: center;
}
.auth-card {
  background: var(--bg-card);
  border-radius: 18px;
  padding: 2.5em;
  max-width: 420px;
  width: 90%;
  box-shadow: 0 24px 60px rgba(13, 22, 44, 0.35);
}
.auth-card__logo { height: 28px; margin-bottom: 1.4em; }
.auth-card h1 { font-size: 1.4em; margin-bottom: 0.3em; }
.auth-card__subtitle {
  color: var(--text-muted);
  font-size: 0.95em;
  line-height: 1.55;
  margin-bottom: 1.5em;
}
.auth-card__error {
  font-size: 0.85em;
  color: var(--err);
  min-height: 1.3em;
  margin: 0.1em 0 0.5em;
}

/* Header user chip + sign-out */
.user-menu {
  display: inline-flex;
  align-items: center;
  gap: 0.6em;
}
.user-menu.hidden { display: none; }
.user-menu__name {
  font-size: 0.85em;
  font-weight: 600;
  color: var(--text-muted);
}

/* --- Confirm modal --- */
.modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 8000;
  background: rgba(13, 22, 44, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1em;
}
.modal {
  background: var(--bg-card);
  border-radius: 14px;
  box-shadow: 0 24px 60px rgba(13, 22, 44, 0.3);
  padding: 1.6em 1.8em;
  max-width: 420px;
  width: 100%;
}
.modal__title { font-size: 1.05em; margin-bottom: 0.6em; }
.modal__body {
  font-size: 0.9em;
  color: var(--text-muted);
  line-height: 1.55;
  white-space: pre-line;
  margin-bottom: 1.4em;
}
.modal__actions {
  display: flex;
  justify-content: flex-end;
  gap: 0.8em;
}

/* --- Global API activity: top progress bar + guard double submits --- */
body.api-busy::after {
  content: '';
  position: fixed;
  top: 0; left: 0; right: 0;
  height: 3px;
  z-index: 9500;
  background: linear-gradient(90deg, var(--brand), var(--brand-green), var(--brand));
  background-size: 200% 100%;
  animation: api-busy-slide 1s linear infinite;
}
@keyframes api-busy-slide {
  from { background-position: 200% 0; }
  to { background-position: 0 0; }
}
body.api-busy .btn-primary,
body.api-busy .btn-danger {
  pointer-events: none;
  opacity: 0.65;
}

/* --- Inline validation --- */
input.invalid, select.invalid, textarea.invalid {
  border-color: var(--err) !important;
  box-shadow: 0 0 0 3px rgba(224, 49, 49, 0.12) !important;
}
.field-error {
  font-size: 0.78em;
  color: var(--err);
  margin: 0.25em 0 0.4em;
}
.form-grid .field-error {
  grid-column: 2;          /* stay under the input column */
  margin-top: -0.3em;
}
.field { flex-wrap: wrap; }
.field .field-error {
  flex-basis: 100%;
  margin-left: 120px;      /* align under the input (label width) */
}

/* --- Skeleton loading placeholders --- */
.skel-group {
  display: flex;
  flex-direction: column;
  gap: 0.7em;
  padding: 0.4em 0;
}
.skel {
  height: 0.95em;
  border-radius: 6px;
  background: linear-gradient(90deg,
    var(--bg-light) 25%, #f8fafd 40%, var(--bg-light) 60%);
  background-size: 300% 100%;
  animation: skel-shimmer 1.3s ease-in-out infinite;
}
.skel-row td { padding: 0.6em 0.8em; }
.skel-row .skel { width: 100%; }
@keyframes skel-shimmer {
  from { background-position: 100% 0; }
  to { background-position: -100% 0; }
}

/* --- Empty states --- */
.empty-state {
  text-align: center;
  padding: 2.2em 1em;
  color: var(--text-dim);
}
.empty-state svg {
  width: 40px;
  height: 40px;
  stroke: var(--border-strong);
  margin-bottom: 0.6em;
}
.empty-state p { font-size: 0.9em; line-height: 1.5; }

/* --- Accessibility --- */
button:focus-visible,
a:focus-visible,
select:focus-visible,
input:focus-visible,
[tabindex]:focus-visible {
  outline: 2px solid var(--brand);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* ── Security page: IP filter entry list ── */
.ipf-addrow { display: flex; gap: 0.5em; max-width: 440px; }
.ipf-addrow input { flex: 1; }
.ipf-list { list-style: none; margin: 0; padding: 0; max-width: 440px; }
.ipf-list li {
  display: flex; align-items: center; gap: 0.6em;
  padding: 0.4em 0.6em; border: 1px solid var(--border-strong);
  border-radius: 8px; margin-bottom: 0.4em; background: var(--bg-card);
}
.ipf-list li code { flex: 1; }
.ipf-you {
  font-size: 0.75em; color: var(--ok); background: var(--ok-bg);
  padding: 0.1em 0.5em; border-radius: 999px; font-weight: 600;
}
.ipf-del {
  border: none; background: none; color: var(--text-dim);
  font-size: 1.2em; line-height: 1; cursor: pointer; padding: 0 0.2em;
}
.ipf-del:hover { color: var(--err); }
.btn-link {
  border: none; background: none; color: var(--brand);
  text-decoration: underline; cursor: pointer; font-size: inherit; padding: 0;
}
#ipf-body.is-disabled { opacity: 0.45; pointer-events: none; }

/* ── WiFi page: scan list, signal bars, password row ── */
.wf-list {
  list-style: none; margin: 0; padding: 2px; max-width: 440px;
  /* A busy 2.4GHz band easily yields 20-30 networks: cap the list
   * at ~6 rows and scroll, so the page keeps its shape. */
  max-height: 300px; overflow-y: auto;
}
.wf-list li {
  display: flex; align-items: center; gap: 0.6em;
  padding: 0.4em 0.7em; border: 1px solid var(--border-strong);
  border-radius: 8px; margin-bottom: 0.4em; background: var(--bg-card);
  cursor: pointer;
}
.wf-list li:hover { border-color: var(--brand); }
.wf-list li.sel { border-color: var(--brand); box-shadow: 0 0 0 2px rgba(0, 48, 135, 0.12); }
.wf-ssid { flex: 1; font-weight: 500; }
.wf-bars { width: 16px; height: 13px; flex: none; }
.wf-bars rect { fill: var(--border-strong); }
.wf-bars rect.on { fill: var(--brand); }
.wf-lock { width: 14px; height: 14px; color: var(--text-dim); }
.wf-pwrow { display: flex; gap: 0.5em; max-width: 440px; }
.wf-pwrow input { flex: 1; }
/* Generic password field with a Show/Hide button (mqtt, add-user). */
.pw-row { display: flex; gap: 0.5em; max-width: 440px; }
.pw-row input { flex: 1; }
.pw-eye { white-space: nowrap; }
.wf-eye { white-space: nowrap; }

/* ── Image (ISP) page: preview + controls two-pane ── */
.isp-card { max-width: 1180px; }
.isp-layout { display: flex; gap: 1.2em; align-items: flex-start; }
.isp-preview {
  /* Clear the 60px sticky header, or scrolling tucks the top of the
   * video underneath it. */
  flex: 0 0 46%; position: sticky; top: calc(60px + 1em);
}
.isp-preview video {
  width: 100%; aspect-ratio: 16/9; background: #111;
  border-radius: 8px; display: block; object-fit: contain;
}
.isp-preview-bar {
  display: flex; justify-content: space-between;
  font-size: 0.85em; margin-top: 0.4em;
}
.isp-panel { flex: 1; min-width: 0; }
.isp-chips {
  display: flex; gap: 0.5em; align-items: center; flex-wrap: wrap;
  margin-bottom: 1em;
}
.isp-chip {
  border: 1px solid var(--border-strong); background: var(--bg-card);
  border-radius: 999px; padding: 0.3em 0.9em; cursor: pointer;
  font-size: 0.9em; color: var(--text);
}
.isp-chip:hover { border-color: var(--brand); }
.isp-chip.active {
  background: var(--brand); color: #fff; border-color: var(--brand);
}
@media (max-width: 900px) {
  .isp-layout { flex-direction: column; }
  .isp-preview { position: static; flex: none; width: 100%; }
}

/* ── Playback: content search (B3) ── */
.sc-row { display: flex; gap: 1em; align-items: center; flex-wrap: wrap; margin-bottom: 0.8em; }
.sc-classes { display: flex; gap: 0.4em; }
.sc-chip {
  border: 1px solid var(--border-strong); background: var(--bg-card);
  border-radius: 999px; padding: 0.3em 0.9em; cursor: pointer; font-size: 0.9em;
  color: var(--text);
}
.sc-chip:hover { border-color: var(--brand); }
.sc-chip.active { background: var(--brand); color: #fff; border-color: var(--brand); }
.sc-conf { display: flex; align-items: center; gap: 0.5em; font-size: 0.85em; color: var(--text-muted); }
.sc-range { display: flex; align-items: center; gap: 0.4em; font-size: 0.85em; color: var(--text-muted); }
.sc-range select { padding: 0.25em 0.4em; }
.sc-results { display: flex; flex-wrap: wrap; gap: 0.5em; align-items: flex-start; }
.sc-daygroup {
  flex-basis: 100%; margin: 0.6em 0 0.1em; font-size: 0.85em; font-weight: 600;
  color: var(--text-muted); border-bottom: 1px solid var(--border); padding-bottom: 0.2em;
}
.sc-daygroup:first-child { margin-top: 0; }
.sc-card {
  display: flex; flex-direction: column; align-items: flex-start; gap: 0.15em;
  border: 1px solid var(--border-strong); background: var(--bg-card);
  border-radius: 8px; padding: 0.5em; cursor: pointer; width: 120px;
}
.sc-card:hover { border-color: var(--brand); }
.sc-card.active { border-color: var(--brand); box-shadow: 0 0 0 2px rgba(0,48,135,0.12); }
.sc-card:disabled { opacity: 0.5; cursor: not-allowed; }
.sc-card-thumb { width: 100%; }
.sc-card-thumb img {
  width: 100%; aspect-ratio: 4 / 3; object-fit: cover;
  border-radius: 4px; background: var(--bg-muted); display: block;
}
.sc-card-thumb:empty { display: none; }
.sc-card-class { font-weight: 600; text-transform: capitalize; }
.sc-card-time { font-size: 0.8em; color: var(--text-muted); }
.sc-card-conf { font-size: 0.75em; color: var(--ok); font-weight: 600; }
